  function renderAlerts() {
    var list = document.getElementById('sa-alert-list');
    if (!list) return;
    var search = (document.getElementById('sa-search-input') || {}).value || '';
    search = search.toLowerCase();
    var filtered = saAlertsData.filter(function(a) {
      if (saActiveSev !== 'ALL' && a.sev !== saActiveSev) return false;
      if (saActiveStatus === 'ACKNOWLEDGED') return false;
      if (search && a.title.toLowerCase().indexOf(search) === -1 && a.well.toLowerCase().indexOf(search) === -1 && a.desc.toLowerCase().indexOf(search) === -1) return false;
      return true;
    });
    var countEl = document.getElementById('sa-count-label');
    if (countEl) countEl.textContent = filtered.length + ' / ' + saAlertsData.length + ' alerts';
    var sevMap = {CRITICAL:'critical',HIGH:'high',MEDIUM:'medium',LOW:'low',INFO:'info'};
    var pctMap = {CRITICAL:'crit',HIGH:'high',MEDIUM:'med',LOW:'low',INFO:'info-c'};
    // Platform admin is view-only (no actions). Assigned users can close alerts.
    var isAdmin = (window.__saIsAdmin !== false);
    var html = '';
    filtered.forEach(function(a) {
      var s = sevMap[a.sev] || 'info';
      var pc = pctMap[a.sev] || 'info-c';
      var slaChip = a.slaText ? '<span class="sa-sla">' + a.slaText + '</span>' : '';
      var actions = '';
      if (!isAdmin) {
        actions = '<div class="sa-actions">' +
          '<button class="sa-close-btn" onclick="saCloseAlert(\'' + (a.id || '') + '\')">Close</button>' +
        '</div>';
      }
      html += '<div class="sa-alert sev-' + s + '">' +
        '<div class="sa-alert-dot ' + s + '"></div>' +
        '<div class="sa-alert-body">' +
          '<div class="sa-alert-tags">' +
            '<span class="sa-sev-tag ' + s + '">' + a.sev + '</span>' +
            '<span class="sa-cat-tag ' + a.catClass + '">' + a.cat + '</span>' +
            '<span class="sa-due">Due: ' + a.due + '</span>' +
            slaChip +
          '</div>' +
          '<div class="sa-alert-title">' + a.title + '</div>' +
          '<div class="sa-alert-desc">' + a.desc + '</div>' +
        '</div>' +
        '<div class="sa-alert-right">' +
          '<div class="sa-well-tag wm-well-link" data-wm-well="' + a.well + '" title="Open well details">' + a.well + '</div>' +
          '<div class="sa-meta"><span class="sa-meta-time">' + a.time + '</span><span class="sa-meta-user">' + a.user + '</span></div>' +
          '<div class="sa-pct ' + pc + '">' + a.pct + '%</div>' +
          actions +
        '</div>' +
      '</div>';
    });
    if (!filtered.length) html = '<div class="sa-empty">No alerts to show.</div>';
    list.innerHTML = html;
  }

