  function renderDelayForecast() {
    buildDfQueue();
    buildDfForecastCharts();
  }

  function buildDfQueue() {
    var el = document.getElementById('df-queue-items');
    if (!el) return;
    el.innerHTML = dfQueueData.map(function(q) {
      var nc = q.num===1?'df-qi-num-1':q.num===2?'df-qi-num-2':'df-qi-num-n';
      var tc = q.type==='flowline'?'df-type-fl':q.type==='skid'?'df-type-sk':'df-type-mat';
      var pc = q.prob>=65?'#FF0000':q.prob>=50?'#FFC000':'#60a5fa';
      return '<div class="df-queue-item">'
        +'<div class="df-qi-top">'
          +'<div class="df-qi-left"><div class="df-qi-num '+nc+'">'+q.num+'</div>'
            +'<div><div style="display:flex;align-items:center;gap:7px"><span class="df-qi-po">'+q.po+'</span><span class="df-type-badge '+tc+'">'+q.type+'</span></div>'
            +'<div class="df-qi-meta">'+q.well+' &nbsp;&middot;&nbsp; '+q.sup+'</div></div>'
          +'</div>'
          +'<div class="df-qi-right"><div class="df-qi-prob" style="color:'+pc+'">'+q.prob+'%</div>'
            +'<div class="df-qi-prob-label">late prob.</div>'
            +'<div class="df-qi-bar"><div class="df-qi-bar-fill" style="width:'+q.prob+'%;background:'+pc+'"></div></div>'
            +'<div class="df-qi-priority">Priority: <strong style="color:var(--txt-1)">'+q.pri+'</strong></div>'
          +'</div>'
        +'</div>'
        +'<div class="df-ai-note"><span class="df-ai-icon">&#9432;</span>'
          +'<span><strong style="color:#a78bfa">AI</strong> \u2014 '+q.ai+'</span></div>'
        +'</div>';
    }).join('');
  }

  function buildDfForecastCharts() {
    if (dfBuilt.lead) return; dfBuilt.lead = true;
    var isDark = !document.documentElement.classList.contains('navbar-light');
    var tickColor = isDark ? 'rgba(200,215,240,0.55)' : '#7F7F7F';
    var gridColor = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.06)';
    var legendColor = isDark ? 'rgba(200,215,240,0.65)' : '#7F7F7F';
    var tooltipBg = isDark ? 'rgba(9,23,38,0.95)' : 'rgba(15,23,42,0.9)';

    var lc = document.getElementById('df-leadtime-chart');
    if (lc) {
      if (dfCharts.lead) dfCharts.lead.destroy();
      dfCharts.lead = new Chart(lc, { type:'bar',
        data:{ labels:['P25','Median','P75','Max'], datasets:[
          { label:'Material', data:[12,30,42,55], backgroundColor:'#22d3ee',  borderRadius:3 },
          { label:'Flowline', data:[15,38,45,62], backgroundColor:'#2E75B6', borderRadius:3 },
          { label:'Location', data:[10,28,38,48], backgroundColor:'#22c55e',  borderRadius:3 }
        ]},
        options:{ responsive:true, maintainAspectRatio:false,
          plugins:{ legend:{labels:{color:legendColor,font:{size:10},boxWidth:10}},
            tooltip:{backgroundColor:tooltipBg,bodyColor:'#fff',borderColor:'rgba(255,255,255,0.1)',borderWidth:1}},
          scales:{ x:{grid:{color:gridColor},ticks:{color:tickColor,font:{size:10}},title:{display:true,text:'Lead time (days)',color:tickColor,font:{size:10}}},
            y:{grid:{color:gridColor},ticks:{color:tickColor,font:{size:10}}}}}
      });
    }
    var dc = document.getElementById('df-delay-chart');
    if (dc) {
      if (dfCharts.delay) dfCharts.delay.destroy();
      dfCharts.delay = new Chart(dc, { type:'bar',
        data:{ labels:['C.AA.NIM..FLO.456','4501022933','C.AA.NIM..FLO.312','C.AA.SEF..DS.24#2','C.AA.NIM..FLO.376','CA.AA.SEF..RS.7457'],
          datasets:[{ label:'Pred. Delay', data:[6,6,4,3,3,2],
            backgroundColor:['#22c55e','#FFC000','#FFC000','#22c55e','#22d3ee','#2E75B6'],
            borderRadius:3 }]},
        options:{ indexAxis:'y', responsive:true, maintainAspectRatio:false,
          plugins:{ legend:{labels:{color:legendColor,font:{size:10},boxWidth:8}},
            tooltip:{backgroundColor:tooltipBg,bodyColor:'#fff',borderColor:'rgba(255,255,255,0.1)',borderWidth:1,callbacks:{label:function(ctx){return '+'+ctx.raw+'d predicted';}}}},
          scales:{ x:{grid:{color:gridColor},ticks:{color:tickColor,font:{size:10}},title:{display:true,text:'Predicted delay (days)',color:tickColor,font:{size:10}}},
            y:{grid:{display:false},ticks:{color:tickColor,font:{size:9}}}}}
      });
    }
  }

  function buildDfAnalysisCharts() {
    var isDark = !document.documentElement.classList.contains('navbar-light');
    var tickColor = isDark ? 'rgba(200,215,240,0.55)' : '#7F7F7F';
    var gridColor = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.06)';
    var legendColor = isDark ? 'rgba(200,215,240,0.65)' : '#7F7F7F';
    var tooltipBg = isDark ? 'rgba(9,23,38,0.95)' : 'rgba(15,23,42,0.9)';

    var fb = document.getElementById('df-feat-bars');
    if (fb && !dfBuilt.feat) { dfBuilt.feat = true;
      var feats=[{l:'Vendor historical on-time rate',p:28,c:'#f472b6'},{l:'PO type complexity',p:22,c:'#22d3ee'},{l:'Days since PO placed',p:17,c:'#FFC000'},{l:'Adjacent schedule pressure',p:14,c:'#FF0000'},{l:'Program year / fiscal period',p:11,c:'#60a5fa'},{l:'Well location remoteness',p:8,c:'#00B050'}];
      fb.innerHTML = feats.map(function(f){ return '<div class="df-feat-row"><div class="df-feat-dot" style="background:'+f.c+'"></div><div class="df-feat-label">'+f.l+'</div><div class="df-feat-bar-wrap"><div class="df-feat-bar" style="width:'+f.p+'%;background:'+f.c+'"></div></div><div class="df-feat-val" style="color:'+f.c+'">'+f.p+'%</div></div>'; }).join('');
    }
    if (!dfBuilt.sla) { dfBuilt.sla = true;
      var sc = document.getElementById('df-sla-chart');
      if (sc) {
        if (dfCharts.sla) dfCharts.sla.destroy();
        dfCharts.sla = new Chart(sc, { type:'line',
          data:{ labels:['W3','W4','W5','W6','W7','W8','W9','W10'], datasets:[
            { label:'SLA Compliance %', data:[92,90,87,89,86,85,88,86], borderColor:'#22c55e', backgroundColor:'rgba(0,176,80,0.06)', borderWidth:2, tension:0.4, fill:true, pointRadius:4, pointBackgroundColor:'#22c55e' },
            { label:'90% target', data:[90,90,90,90,90,90,90,90], borderColor:'#ef4444', borderWidth:1.5, borderDash:[6,4], tension:0, fill:false, pointRadius:0 }
          ]},
          options:{ responsive:true, maintainAspectRatio:false,
            plugins:{ legend:{labels:{color:legendColor,font:{size:11},boxWidth:10}}, tooltip:{backgroundColor:tooltipBg,bodyColor:'#fff',borderColor:'rgba(255,255,255,0.1)',borderWidth:1}},
            scales:{ x:{grid:{color:gridColor},ticks:{color:tickColor,font:{size:11}}},
              y:{min:50,max:100,grid:{color:gridColor},ticks:{color:tickColor,font:{size:10}},title:{display:true,text:'SLA %',color:tickColor,font:{size:10}}}}}
        });
      }
    }
  }

  function buildDfFullTable() {
    var tbody = document.getElementById('df-full-tbody');
    if (!tbody || dfBuilt.fulltbl) return; dfBuilt.fulltbl = true;
    tbody.innerHTML = dfFullData.map(function(d) {
      var tc = d.type==='flowline'?'df-type-fl':d.type==='skid'?'df-type-sk':'df-type-mat';
      var pc = d.prob>=60?'#FF0000':d.prob>=40?'#FFC000':'#00B050';
      var rc = d.risk==='HIGH'?'df-risk-high':d.risk==='MEDIUM'?'df-risk-med':'df-risk-low';
      var ec = d.exp.indexOf('P1')===0?'df-exp-p1':d.exp.indexOf('P2')===0?'df-exp-p2':d.exp.indexOf('P3')===0?'df-exp-p3':'df-exp-p4';
      var ac = d.act==='Expedite'?'df-action-exp':'df-action-mon';
      return '<tr>'
        +'<td class="df-tbl-po">'+d.po+'</td>'
        +'<td><span class="df-type-badge '+tc+'">'+d.type+'</span></td>'
        +'<td class="df-tbl-well">'+d.well+'</td>'
        +'<td style="font-size:9pt;color:var(--txt-muted)">'+d.placed+'</td>'
        +'<td style="font-size:9pt;color:var(--txt-muted)">'+d.expDel+'</td>'
        +'<td class="'+(d.actual==='Delivered'?'df-actual-del':'df-actual-pend')+'">'+d.actual+'</td>'
        +'<td class="'+(d.late?'df-lead-late':'df-lead-ok')+'">'+d.lead+'</td>'
        +'<td style="color:var(--txt-muted)">'+d.sla+'</td>'
        +'<td class="'+(d.late?'df-late':'df-ok')+'">'+(d.late?'\u25b3 LATE':'\u2713 OK')+'</td>'
        +'<td><span class="df-prob-bar"><span class="df-prob-fill" style="width:'+d.prob+'%;background:'+pc+'"></span></span><span style="color:'+pc+';font-weight:600">'+d.prob+'%</span></td>'
        +'<td class="'+(d.pred!=='0d'?'df-pred-pos':'df-pred-zero')+'">'+d.pred+'</td>'
        +'<td><span class="df-risk-badge '+rc+'">'+d.risk+'</span></td>'
        +'<td><span class="df-exp-badge '+ec+'">'+d.exp+'</span></td>'
        +'<td><span class="df-action-btn '+ac+'">&#9654; '+d.act+'</span></td>'
        +'</tr>';
    }).join('');
  }

