  function renderCommission(){
    var tbody = document.getElementById('comm-table-tbody');
    if(tbody && !tbody.dataset.built){
      tbody.dataset.built = '1';
      tbody.innerHTML = commTableData.map(function(r){
        var stCls = r.status==='Completed' ? 'comm-status-completed' : r.status==='Critical' ? 'comm-status-critical' : 'comm-status-progress';
        return '<tr>'
          +'<td><span class="comm-well-link">'+r.well+'</span></td>'
          +'<td>'+r.expOn+'</td>'
          +'<td>'+r.expOff+'</td>'
          +'<td>'+r.actOn+'</td>'
          +'<td>'+r.actOff+'</td>'
          +'<td><span class="comm-type-badge">'+r.type+'</span></td>'
          +'<td><span class="comm-status-badge '+stCls+'">'+r.status+'</span></td>'
          +'</tr>';
      }).join('');
    }

    setTimeout(function(){
      var cEl = document.getElementById('comm-chart-progress');
      if(cEl && !commChartProgress){
        var isDark = !document.documentElement.classList.contains('navbar-light');
        var gc = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)';
        var tc = isDark ? '#c7cfe0' : '#3a3a5c';
        var wells = commChartData.map(function(r){ return r.well; });
        var pcts = commChartData.map(function(r){ return r.pct; });
        var colors = pcts.map(function(v){
          if(v >= 80) return '#00B050';
          if(v >= 50) return '#FFC000';
          return '#FF0000';
        });
        commChartProgress = new Chart(cEl, {
          type:'bar',
          data:{
            labels:wells,
            datasets:[{ label:'Overall %', data:pcts, backgroundColor:colors, borderRadius:2, barThickness:14 }]
          },
          options:{
            responsive:true, maintainAspectRatio:false,
            plugins:{ legend:{ position:'bottom', labels:{ color:tc, boxWidth:8, font:{size:10} } } },
            scales:{
              x:{ grid:{display:false}, ticks:{color:tc, font:{size:8}, maxRotation:90, minRotation:45} },
              y:{ title:{display:true, text:'%', color:tc, font:{size:9}}, grid:{color:gc}, ticks:{color:tc, font:{size:9}, stepSize:50}, min:0, max:100 }
            }
          }
        });
      }
    }, 80);
  }

