        if(w.proc) pills+='<span class="rca-pill rca-pill-proc">Procurement: '+w.proc+'d</span>';
        if(w.con) pills+='<span class="rca-pill rca-pill-const">Construction: '+w.con+'d</span>';
        if(w.rig_d) pills+='<span class="rca-pill rca-pill-rig">Rig/Drilling: '+w.rig_d+'d</span>';
        if(w.comm) pills+='<span class="rca-pill rca-pill-comm">Commissioning: '+w.comm+'d</span>';
        return '<div class="rca-well-card">'
          +'<div class="rca-well-head">'
