  function fdEsc(s){ return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }

  function fdStatusPill(s){
    if(s==='published') return '<span class="fd-pill fd-pill-active">Active</span>';
    if(s==='error')     return '<span class="fd-pill fd-pill-error">Error</span>';
    return                     '<span class="fd-pill fd-pill-draft">Draft</span>';
  }
  function fdTriggerTag(t){
    var icon = '';
    if(t==='record')   icon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:11px;height:11px"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>';
    if(t==='schedule') icon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:11px;height:11px"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
    if(t==='module')   icon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:11px;height:11px"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>';
    var label = t==='record'?'Data Record':t==='schedule'?'Time-Based':'Module Event';
    return '<span class="fd-trig-tag">'+icon+label+'</span>';
  }

  var fdGridInstance = null;

  function fdRenderList(){
    var q = (document.getElementById('fdSearch')||{}).value || '';
    q = q.toLowerCase().trim();
    var st = (document.getElementById('fdStatusFilter')||{}).value || '';
    var tt = (document.getElementById('fdTriggerFilter')||{}).value || '';

    var rows = fdFlows.filter(function(f){
      if(st && f.status!==st) return false;
      if(tt && f.trigger!==tt) return false;
      if(q){
        var hay = (f.name+' '+f.desc+' '+f.owner+' '+f.triggerLabel).toLowerCase();
        if(hay.indexOf(q)===-1) return false;
      }
      return true;
    });

    var gridDiv = document.getElementById('fdFlowsGrid'); if(!gridDiv) return;
    var badge = document.getElementById('fdRecordsBadge');
    if(badge) badge.textContent = rows.length + ' flow' + (rows.length===1?'':'s');

    var cnt = document.getElementById('fdListCount');
    if(cnt) cnt.textContent = rows.length+' flow'+(rows.length===1?'':'s');

    if (fdGridInstance && typeof fdGridInstance.setGridOption === 'function') {
      if (gridDiv.querySelector('.ag-root-wrapper')) {
        fdGridInstance.setGridOption('rowData', rows);
        return;
      }
      try { fdGridInstance.destroy(); } catch(e) {}
      fdGridInstance = null;
    }

    var isDark = !document.documentElement.classList.contains('navbar-light');
    gridDiv.className = isDark ? 'ag-theme-alpine-dark' : 'ag-theme-alpine';

    function fdFlowNameCell(params) {
      return '<span class="fd-flow-name" onclick="fdOpenEditor('+params.data.id+')">'+fdEsc(params.value)+'</span>';
    }
    function fdStatusCell(params) {
      var s = params.value;
      var dk = !document.documentElement.classList.contains('navbar-light');
      if(s==='published') return '<span style="display:inline-flex;align-items:center;gap:6px;color:#00B050;font-weight:700;font-size:9pt;letter-spacing:0.4px;text-transform:uppercase"><span style="width:6px;height:6px;border-radius:50%;background:currentColor;flex-shrink:0"></span>Active</span>';
      if(s==='error')     return '<span style="display:inline-flex;align-items:center;gap:6px;color:#FF0000;font-weight:700;font-size:9pt;letter-spacing:0.4px;text-transform:uppercase"><span style="width:6px;height:6px;border-radius:50%;background:currentColor;flex-shrink:0"></span>Error</span>';
      return '<span style="display:inline-flex;align-items:center;gap:6px;color:'+(dk?'#A5A5A5':'#7F7F7F')+';font-weight:700;font-size:9pt;letter-spacing:0.4px;text-transform:uppercase"><span style="width:6px;height:6px;border-radius:50%;background:currentColor;flex-shrink:0"></span>Draft</span>';
    }
    function fdTriggerCell(params) {
      var t = params.value;
      var icon = '';
      if(t==='record')   icon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:11px;height:11px"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>';
      if(t==='schedule') icon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:11px;height:11px"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
      if(t==='module')   icon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:11px;height:11px"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>';
      var label = t==='record'?'Data Record':t==='schedule'?'Time-Based':'Module Event';
      return '<span class="fd-trig-tag">'+icon+label+'</span>';
    }
    function fdActionsCell(params) {
      var id = params.data.id;
      return '<div class="fd-row-actions">'+
        '<button class="fd-btn fd-btn-ghost" title="Open" onclick="fdOpenEditor('+id+')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>'+
        '<button class="fd-btn fd-btn-ghost" title="Duplicate" onclick="fdDuplicateFlow('+id+')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg></button>'+
        '<button class="fd-btn fd-btn-ghost fd-btn-danger" title="Delete" onclick="fdDeleteFlow('+id+')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></button>'+
      '</div>';
    }

    var columnDefs = [
      { headerName:'Flow Name', field:'name', width:240, sortable:true, filter:true, cellRenderer: fdFlowNameCell },
      { headerName:'Status', field:'status', width:130, sortable:true, filter:true, cellRenderer: fdStatusCell },
      { headerName:'Initiator', field:'trigger', width:150, sortable:true, filter:true, cellRenderer: fdTriggerCell },
      { headerName:'Description', field:'desc', flex:1, minWidth:200, sortable:true, filter:true, cellStyle:{ fontSize:'9pt', color:'var(--txt-2)' }, tooltipField:'desc' },
      { headerName:'Last Modified', field:'modified', width:145, sortable:true, filter:true, cellStyle:{ fontFamily:'var(--font-family-mono)', fontSize:'9pt', color:'var(--txt-2)' } },
      { headerName:'Last Run', field:'lastRun', width:155, sortable:true, filter:true, cellStyle:{ fontFamily:'var(--font-family-mono)', fontSize:'9pt', color:'var(--txt-2)' } },
      { headerName:'Owner', field:'owner', width:130, sortable:true, filter:true },
      { headerName:'Actions', field:'actions', width:120, sortable:false, filter:false, cellRenderer: fdActionsCell }
    ];

    var gridOptions = {
      columnDefs: columnDefs,
      rowData: rows,
      defaultColDef: { resizable: true, sortable: true, filter: true },
      animateRows: true,
      pagination: true,
      paginationPageSize: 20,
      paginationPageSizeSelector: [10, 20, 50],
      domLayout: 'normal',
      rowHeight: 50,
      headerHeight: 44,
      suppressCellFocus: false,
      enableCellTextSelection: true,
      suppressMovableColumns: false
    };

    fdGridInstance = agGrid.createGrid(gridDiv, gridOptions);
  }

  function fdDuplicateFlow(id){
    var src = fdFlows.find(function(f){return f.id===id;}); if(!src) return;
    var copy = JSON.parse(JSON.stringify(src));
    copy.id = Math.max.apply(null, fdFlows.map(function(f){return f.id;})) + 1;
    copy.name = src.name + ' (copy)';
    copy.status = 'draft';
    copy.modified = new Date().toISOString().slice(0,10);
    copy.lastRun = '—';
    fdFlows.unshift(copy);
    if(fdGridInstance){ try{fdGridInstance.destroy();}catch(e){} fdGridInstance=null; }
    fdRenderList();
  }
  function fdDeleteFlow(id){
    var f = fdFlows.find(function(x){return x.id===id;}); if(!f) return;
    if(!confirm('Delete the flow "'+f.name+'"? This cannot be undone.')) return;
    fdFlows = fdFlows.filter(function(x){return x.id!==id;});
    if(fdGridInstance){ try{fdGridInstance.destroy();}catch(e){} fdGridInstance=null; }
    fdRenderList();
  }

  // ───────────────────────────────────────────────
  // EDITOR PAGE
  // ───────────────────────────────────────────────
  function fdOpenEditor(id){
    if(id){
      var f = fdFlows.find(function(x){return x.id===id;});
      if(!f) return;

      // Build operations — Well Delay Remediation has a custom seeded sequence
      var ops;
      if(id === 11){
        ops = fdBuildRemediationOps();
      } else if(id === 12){
        ops = fdBuildRemediationOpsUI();
      } else if(id === 13){
        ops = fdBuildRPAOps();
      } else if(id === 14){
        ops = fdBuildFormSubmissionOps(f.formName || 'Catalogue Form');
      } else if(id === 15){
        ops = fdBuildPermitToWorkOps();
      } else {
        ops = [
          { id: Date.now()+1, name: 'Request Approval', kind:'builtin' },
          { id: Date.now()+2, name: 'Save Record', kind:'builtin' }
        ];
      }

      fdEditorState = {
        flowId: f.id,
        flowName: f.name,
        status: f.status==='published' ? 'published' : 'draft',
        triggerCat: f.trigger,
        triggerOption: f.isFormFlow ? 'On Catalogue Submit'
                       : ((f.triggerLabel||'').replace(/^.*?·\s*/,'').replace(/^.*?— ?/,'').split(' at ')[0] || (fdTriggerCatalog[f.trigger]||{}).options?.[0] || null),
        // Use the full label so the summary reads naturally
        triggerSummaryOverride: f.triggerLabel,
        triggerFormId: f.formId || null,
        triggerFormName: f.formName || null,
        operations: ops,
        selectedOpId: null,
        recovery: false,
        pickerCat: f.trigger || 'record',
        ddSearch: '',
        isLiveFlow: !!f.isLive
      };
    } else {
      // New flow
      fdEditorState = {
        flowId: null,
        flowName: 'MyProcessFlow',
        status: 'draft',
        triggerCat: null,
        triggerOption: null,
        triggerSummaryOverride: null,
        operations: [],
        selectedOpId: null,
        recovery: false,
        pickerCat: 'record',
        ddSearch: ''
      };
    }
    navigate('flowedit', null);
  }

  // Seeds the operation list for the Well Delay Remediation workflow.
  // The final step is a real ServiceNow incident creation (kind:'external', isReal:true).
  function fdBuildRemediationOps(){
    var snowConn = fdConnections.find(function(c){return c.type==='ServiceNow';});
    var snowAct  = snowConn && (snowConn.actions||[]).find(function(a){return a.id==='snow-incident';});
    var t0 = Date.now();
    return [
      {
        id: t0+1, kind:'builtin',
        name: 'Query active wells from Vise',
        desc: 'For each well with status = active, collect the well_id for downstream evaluation.',
        category: 'data-query', mockOnly: true
      },
      {
        id: t0+2, kind:'builtin',
        name: 'For each well — call AI Agent: Well Delay Predictor',
        desc: 'Invoke the Well Delay Predictor agent (which itself delegates to the Well Progress Reader). Capture verdict, confidence, and estimated delay days.',
        category: 'agent-call', mockOnly: true,
        agentId: 2
      },
      {
        id: t0+3, kind:'builtin',
        name: 'Filter — keep wells where will_be_delayed = true AND confidence > 0.7',
        desc: 'Discard wells the agent classified as on-track or low-confidence.',
        category: 'filter', mockOnly: true
      },
      {
        id: t0+4, kind:'builtin',
        name: 'AI Recommendation — generate crew-expansion remediation plan',
        desc: 'Reasoning model proposes "increase crew headcount by N" based on delay magnitude and historical recovery patterns. Output: { extra_workers, justification }.',
        category: 'ai-suggest', mockOnly: true
      },
      {
        id: t0+5, kind:'builtin',
        name: 'Look up crew calendar (mock)',
        desc: 'Pull crew assignment data from the field-ops scheduling system. Returns crew records with allocation_status.',
        category: 'data-query', mockOnly: true
      },
      {
        id: t0+6, kind:'builtin',
        name: 'Filter — only crews where allocation_status = unallocated',
        desc: 'Skip crews that are already booked. Avoids double-booking and notification spam.',
        category: 'filter', mockOnly: true
      },
      {
        id: t0+7,
        kind: 'external',
        name: 'Create ServiceNow Incident (LIVE)',
        connectionId: snowConn ? snowConn.id : 2,
        actionId: 'snow-incident',
        actionLabel: snowAct ? snowAct.label : 'Create Incident (LIVE)',
        actionMethod: 'POST',
        actionPath: '/api/now/table/incident',
        isReal: true,
        config: {
          body: '{\n  "short_description": "Well delay remediation — crew assignment required",\n  "description": "Auto-generated by Well Delay Remediation flow.\\n\\nWell: {{well_id}}\\nDelay risk: {{estimated_delay_days}} days at {{confidence}} confidence.\\nRecommended action: assign {{extra_workers}} additional workers from unallocated crew {{crew_id}}.",\n  "urgency": "2",\n  "impact": "2",\n  "category": "inquiry",\n  "caller_id": "admin"\n}',
          headers: {}
        }
      }
    ];
  }

