  // RPA flow — bot reads an Excel file the user uploads, then iterates and
  // creates one ServiceNow incident per row via the REST connector.
  function fdBuildRPAOps(){
    var snowConn = fdConnections.find(function(c){return c.type==='ServiceNow';});
    var snowAct  = snowConn && (snowConn.actions||[]).find(function(a){return a.id==='snow-incident';});
    var t0 = Date.now();
    return [
      {
        id: t0+1, kind:'builtin',
        name: 'Initialize RPA bot · acquire ServiceNow connection',
        desc: 'Bot starts up, validates the ServiceNow REST credential, and reserves a worker slot. Equivalent to UiPath\'s "Open Application + Get Credential" or a Robocorp robot startup.',
        category: 'rpa-init'
      },
      {
        id: t0+2, kind:'builtin',
        name: 'Open Excel: Servicenow worker incidents.xlsx',
        desc: 'Bot opens the source Excel workbook and selects the first sheet. Real Excel parsing happens in-browser via SheetJS — equivalent to UiPath\'s "Excel Application Scope".',
        category: 'rpa-open-xlsx'
      },
      {
        id: t0+3, kind:'builtin',
        name: 'Read all rows from worksheet',
        desc: 'Iterate the worksheet and convert each row to a structured object. Equivalent to UiPath\'s "Read Range Workbook".',
        category: 'rpa-read-rows'
      },
      {
        id: t0+4, kind:'builtin',
        name: 'Validate each row · drop invalid records',
        desc: 'Check required columns (well_id, short_description) and value ranges (urgency/impact in 1..3). Invalid rows are flagged and skipped.',
        category: 'rpa-validate'
      },
      {
        id: t0+5,
        kind: 'external',
        name: 'For each valid row → Create ServiceNow Incident (LIVE REST, looped)',
        connectionId: snowConn ? snowConn.id : 2,
        actionId: 'snow-incident',
        actionLabel: snowAct ? snowAct.label : 'Create Incident (LIVE)',
        actionMethod: 'POST',
        actionPath: '/api/now/table/incident',
        isReal: true,
        isRPALoop: true,
        config: {
          body: '{\n  "short_description": "{{short_description}}",\n  "description": "{{description}}",\n  "urgency": "{{urgency}}",\n  "impact": "{{impact}}",\n  "category": "{{category}}",\n  "caller_id": "{{caller_id}}"\n}',
          headers: {}
        }
      },
      {
        id: t0+6, kind:'builtin',
        name: 'Generate summary report · log run history',
        desc: 'Compile success/failure counts, attach the list of created INC numbers, and post the run record into the bot orchestrator log.',
        category: 'rpa-summary'
      }
    ];
  }

