  function renderFlowEdit(){
    var s = fdEditorState;
    var nameEl = document.getElementById('fdFlowNameInput');
    if(nameEl) nameEl.value = s.flowName;

    var crumb = document.getElementById('fdEditCrumb');
    if(crumb) crumb.textContent = s.flowId ? s.flowName : 'New Flow';

    var chip = document.getElementById('fdStatusChip');
    if(chip){
      if(s.status==='published'){ chip.textContent = 'Published'; chip.classList.add('published'); }
      else { chip.textContent = 'Draft'; chip.classList.remove('published'); }
    }

    // Recovery toggle
    var rec = document.getElementById('fdRecoveryToggle');
    if(rec) rec.checked = !!s.recovery;

    // Trigger view: picker vs summary
    fdRenderTriggerZone();

    // Operations area
    fdRenderOps();

    // Right-side data panel
    fdRenderDataPanel();

    // Wire flow name input
    if(nameEl && !nameEl.dataset.wired){
      nameEl.dataset.wired = '1';
      nameEl.addEventListener('input', function(){
        fdEditorState.flowName = nameEl.value || 'Untitled flow';
        var c = document.getElementById('fdEditCrumb');
        if(c) c.textContent = fdEditorState.flowName;
      });
    }

    // Close dropdown when clicking outside
    if(!document._fdDdWired){
      document._fdDdWired = true;
      document.addEventListener('click', function(e){
        var panel = document.getElementById('fdDdPanel');
        var trig = document.getElementById('fdDdTrigger');
        if(!panel || !trig) return;
        if(!panel.classList.contains('open')) return;
        if(panel.contains(e.target) || trig.contains(e.target)) return;
        panel.classList.remove('open');
        trig.classList.remove('open');
      });
    }
  }

  function fdRenderTriggerZone(){
    var s = fdEditorState;
    var picker = document.getElementById('fdTriggerPicker');
    var summary = document.getElementById('fdTriggerSummary');
    if(!picker || !summary) return;

    if(s.triggerCat && s.triggerOption){
      picker.style.display = 'none';
      summary.style.display = '';
      var catLabel = (fdTriggerCatalog[s.triggerCat]||{}).label || '';
      var summaryText = s.triggerSummaryOverride || (catLabel + ' · ' + s.triggerOption);
      document.getElementById('fdTriggerSummaryText').innerHTML =
        'Initiator — <strong>'+fdEsc(summaryText)+'</strong>';
    } else {
      picker.style.display = '';
      summary.style.display = 'none';
      // Default the picker label
      var lbl = document.getElementById('fdDdLabel');
      if(lbl){ lbl.textContent = 'Select Initiator Type'; lbl.classList.add('placeholder'); }
      // Render options for current pickerCat
      fdRenderDdOptions();
    }
  }

  function fdToggleDd(){
    var panel = document.getElementById('fdDdPanel');
    var trig = document.getElementById('fdDdTrigger');
    if(!panel || !trig) return;
    var open = panel.classList.toggle('open');
    trig.classList.toggle('open', open);
    if(open) fdRenderDdOptions();
  }

  function fdSelectCat(cat){
    fdEditorState.pickerCat = cat;
    document.querySelectorAll('#fdDdCats .fd-dd-cat').forEach(function(el){
      el.classList.toggle('active', el.getAttribute('data-cat')===cat);
    });
    fdRenderDdOptions();
  }

  function fdDdSearch(v){
    fdEditorState.ddSearch = (v||'').toLowerCase();
    fdRenderDdOptions();
  }

  function fdRenderDdOptions(){
    var box = document.getElementById('fdDdOpts');
    if(!box) return;
    var cat = fdEditorState.pickerCat;
    var entry = fdTriggerCatalog[cat] || {options:[]};
    var q = fdEditorState.ddSearch || '';
    var opts = entry.options.filter(function(o){ return !q || o.toLowerCase().indexOf(q)!==-1; });

    var html = '<div class="fd-dd-opts-header">'+fdEsc(entry.label||'')+'</div>';
    if(opts.length===0){
      html += '<div class="fd-dd-opt" style="opacity:0.5;cursor:default"><span>No matches</span></div>';
    } else {
      opts.forEach(function(o){
        html += '<div class="fd-dd-opt" onclick="fdPickTrigger(\''+cat+'\',\''+fdEsc(o).replace(/'/g,"\\'")+'\')">'+
                  '<span>'+fdEsc(o)+'</span>'+
                  '<span class="fd-dd-opt-info"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg></span>'+
                '</div>';
      });
    }
    box.innerHTML = html;
  }

  function fdPickTrigger(cat, opt){
    fdEditorState.triggerCat = cat;
    fdEditorState.triggerOption = opt;
    fdEditorState.triggerSummaryOverride = null;
    fdEditorState.triggerFormId = null;
    fdEditorState.triggerFormName = null;
    var panel = document.getElementById('fdDdPanel');
    var trig = document.getElementById('fdDdTrigger');
    if(panel) panel.classList.remove('open');
    if(trig)  trig.classList.remove('open');

    // Tie the trigger to a specific catalogue form when the option is
    // "On Catalogue Submit" — the workflow only fires for that form.
    if(cat === 'record' && opt === 'On Catalogue Submit'){
      fdPromptCatalogueForm();
      return;
    }
    fdRenderTriggerZone();
    fdRenderDataPanel();
  }

  // Open a styled modal that lets the user pick which catalogue form's
  // submission should trigger the flow. Reads the live catalogue library
  // from localStorage (deduped by name) and renders one card per form.
  function fdPromptCatalogueForm(){
    var forms = [];
    try {
      var raw = localStorage.getItem('altasnim.catalogue.forms');
      if(raw){
        var arr = JSON.parse(raw);
        if(Array.isArray(arr)){
          // Dedupe by lowercased name so duplicate seed entries don't show twice
          var seen = {};
          forms = arr.filter(function(f){
            if(!f || !f.name) return false;
            var k = f.name.toLowerCase();
            if(seen[k]) return false;
            seen[k] = true;
            return true;
          }).map(function(f){
            return {
              id: f.id,
              name: f.name,
              description: f.description || '',
              fieldCount: f.fieldCount || (f.fields && f.fields.length) || 0
            };
          });
        }
      }
    } catch(e){}

    fdShowFormPicker(forms);
  }

  function fdShowFormPicker(forms){
    // Remove any existing instance
    var existing = document.getElementById('fdFormPickerBackdrop');
    if(existing) existing.remove();

    var rows;
    if(forms.length === 0){
      rows = '<div class="fd-form-picker-empty">'+
        'No catalogue forms found. Create one in Catalogue → Request Forms first.'+
        '</div>';
    } else {
      rows = forms.map(function(f, i){
        var icon = fdFormPickerIcon(f.name);
        return ''+
          '<div class="fd-form-picker-card" data-name="'+fdEsc(f.name).toLowerCase()+'" '+
            'onclick="fdSelectCatalogueForm(\''+fdEsc(f.id||'').replace(/\'/g,"\\\\'")+'\', \''+fdEsc(f.name).replace(/\'/g,"\\\\'")+'\')">'+
            '<div class="fd-form-picker-card-icon" data-icon="'+icon+'">'+
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+
                '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>'+
                '<polyline points="14 2 14 8 20 8"/>'+
                '<line x1="9" y1="13" x2="15" y2="13"/>'+
                '<line x1="9" y1="17" x2="13" y2="17"/>'+
              '</svg>'+
            '</div>'+
            '<div class="fd-form-picker-card-body">'+
              '<div class="fd-form-picker-card-name">'+fdEsc(f.name)+'</div>'+
              '<div class="fd-form-picker-card-desc">'+fdEsc(f.description || 'No description')+'</div>'+
            '</div>'+
            '<div class="fd-form-picker-card-meta">'+
              (f.fieldCount > 0 ? '<span class="fd-form-picker-pill">'+f.fieldCount+' fields</span>' : '')+
              '<span class="fd-form-picker-card-arrow">'+
                '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg>'+
              '</span>'+
            '</div>'+
          '</div>';
      }).join('');

      // "Any form" wildcard option at the bottom
      rows += ''+
        '<div class="fd-form-picker-card any" onclick="fdSelectCatalogueForm(\'\', \'\')">'+
          '<div class="fd-form-picker-card-icon" data-icon="any">'+
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+
              '<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>'+
            '</svg>'+
          '</div>'+
          '<div class="fd-form-picker-card-body">'+
            '<div class="fd-form-picker-card-name">Any form</div>'+
            '<div class="fd-form-picker-card-desc">Trigger fires for every catalogue submission</div>'+
          '</div>'+
          '<div class="fd-form-picker-card-meta">'+
            '<span class="fd-form-picker-card-arrow">'+
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg>'+
            '</span>'+
          '</div>'+
        '</div>';
    }

    var modalHtml = ''+
      '<div class="fd-form-picker-backdrop" id="fdFormPickerBackdrop" onclick="fdCloseFormPicker(event)">'+
        '<div class="fd-form-picker-modal" onclick="event.stopPropagation()">'+
          '<div class="fd-form-picker-head">'+
            '<div class="fd-form-picker-head-icon">'+
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>'+
            '</div>'+
            '<div class="fd-form-picker-head-meta">'+
              '<h3>Select a catalogue form</h3>'+
              '<div class="fd-form-picker-sub">The flow will only fire when this form is submitted.</div>'+
            '</div>'+
            '<button class="fd-form-picker-close" onclick="fdCloseFormPicker()" title="Close">'+
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>'+
            '</button>'+
          '</div>'+
          (forms.length > 0 ? ''+
            '<div class="fd-form-picker-search">'+
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>'+
              '<input id="fdFormPickerSearch" placeholder="Search forms..." oninput="fdFormPickerFilter(this.value)" />'+
            '</div>' : '')+
          '<div class="fd-form-picker-list" id="fdFormPickerList">'+rows+'</div>'+
          '<div class="fd-form-picker-foot">'+
            '<button class="fd-btn" onclick="fdCloseFormPicker()">Cancel</button>'+
          '</div>'+
        '</div>'+
      '</div>';

    var wrapper = document.createElement('div');
    wrapper.innerHTML = modalHtml;
    document.body.appendChild(wrapper.firstElementChild);

    // Autofocus the search box
    setTimeout(function(){
      var s = document.getElementById('fdFormPickerSearch');
      if(s) s.focus();
    }, 50);
  }

  // Map form name → icon palette for the picker tile
  function fdFormPickerIcon(name){
    var n = (name || '').toLowerCase();
    if(n.indexOf('site') !== -1)        return 'site';
    if(n.indexOf('crew') !== -1)        return 'crew';
    if(n.indexOf('incident') !== -1)    return 'incident';
    if(n.indexOf('material') !== -1)    return 'material';
    if(n.indexOf('ppe') !== -1)         return 'ppe';
    if(n.indexOf('permit') !== -1 || n.indexOf('ptw') !== -1) return 'permit';
    if(n.indexOf('lift') !== -1)        return 'lifting';
    if(n.indexOf('toolbox') !== -1)     return 'toolbox';
    if(n.indexOf('engineering') !== -1 || n.indexOf('moc') !== -1 || n.indexOf('change') !== -1) return 'moc';
    if(n.indexOf('travel') !== -1 || n.indexOf('logistics') !== -1) return 'travel';
    return 'form';
  }

  window.fdFormPickerFilter = function(q){
    var query = (q || '').toLowerCase().trim();
    var list = document.getElementById('fdFormPickerList');
    if(!list) return;
    list.querySelectorAll('.fd-form-picker-card').forEach(function(card){
      if(card.classList.contains('any')){ card.style.display = ''; return; }
      var name = card.getAttribute('data-name') || '';
      card.style.display = (!query || name.indexOf(query) !== -1) ? '' : 'none';
    });
  };

  window.fdSelectCatalogueForm = function(formId, formName){
    if(formId && formName){
      fdEditorState.triggerSummaryOverride = 'On Catalogue Submit · ' + formName;
      fdEditorState.triggerFormId = formId;
      fdEditorState.triggerFormName = formName;
    } else {
      fdEditorState.triggerSummaryOverride = 'On Catalogue Submit · (any form)';
      fdEditorState.triggerFormId = null;
      fdEditorState.triggerFormName = null;
    }
    fdCloseFormPicker();
    fdRenderTriggerZone();
    fdRenderDataPanel();
  };

  window.fdCloseFormPicker = function(ev){
    if(ev && ev.target && ev.target.id !== 'fdFormPickerBackdrop') return;
    var el = document.getElementById('fdFormPickerBackdrop');
    if(el) el.remove();
  };

  function fdEditTrigger(){
    // Switch back to picker, retain category
    fdEditorState.triggerCat = null;
    fdEditorState.triggerOption = null;
    fdEditorState.triggerSummaryOverride = null;
    fdRenderTriggerZone();
    fdRenderDataPanel();
  }

  function fdCancelTrigger(){
    if(fdEditorState.triggerCat){
      fdEditorState.triggerCat = null;
      fdEditorState.triggerOption = null;
      fdEditorState.triggerSummaryOverride = null;
      fdRenderTriggerZone();
      fdRenderDataPanel();
    } else {
      // No trigger configured — cancel exits the editor
      navigate('flowdesigner', document.getElementById('nav-flowdesigner'));
    }
  }

  // ── Operations ──────────────────────────────────
  function fdRenderOps(){
    var zone = document.getElementById('fdOpsZone');
    if(!zone) return;
    var s = fdEditorState;
    var html = '';

    s.operations.forEach(function(op, idx){
      var sel = (op.id===s.selectedOpId) ? ' selected' : '';
      var isExt = op.kind === 'external';
      var conn = isExt ? fdConnections.find(function(c){return c.id===op.connectionId;}) : null;
      var bullet, nameBlock;

      if(isExt && conn){
        // External integration row — bullet uses the connection's logo color
        bullet = '<div class="fd-conn-logo '+fdConnLogoClass(conn.type)+'" style="width:30px;height:30px;border-radius:50%">'+fdConnLogoSvg(conn.type)+'</div>';
        nameBlock = ''+
          '<div class="fd-op-name-wrap">'+
            '<span class="fd-op-name">'+fdEsc(op.name)+'</span>'+
            '<span class="fd-op-required">*</span>'+
            '<span class="fd-op-ext-meta">via <strong>'+fdEsc(conn.name)+'</strong> · '+fdEsc(op.actionMethod||'')+' '+fdEsc(op.actionPath||'')+'</span>'+
          '</div>';
      } else {
        bullet = '<span class="fd-op-bullet"></span>';
        nameBlock = ''+
          '<div class="fd-op-name-wrap">'+
            '<span class="fd-op-name">'+fdEsc(op.name)+'</span>'+
            '<span class="fd-op-required">*</span>'+
          '</div>';
      }

      html += ''+
        '<div class="fd-op-row'+sel+'" onclick="fdSelectOp('+op.id+')">'+
          '<div class="fd-op-drag" title="Drag to reorder"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="9" cy="6" r="1"/><circle cx="9" cy="12" r="1"/><circle cx="9" cy="18" r="1"/><circle cx="15" cy="6" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="15" cy="18" r="1"/></svg></div>'+
          '<div class="fd-op-num">'+(idx+1)+'</div>'+
          bullet +
          nameBlock +
          '<span class="fd-op-help" title="Help"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></span>'+
          '<div class="fd-op-tools" onclick="event.stopPropagation()">'+
            '<div class="fd-op-tool" title="Duplicate" onclick="fdDuplicateOp('+op.id+')"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg></div>'+
            '<div class="fd-op-tool" title="Add to subflow"><svg viewBox="0 0 24 24"><polyline points="16 3 21 3 21 8"/><line x1="4" y1="20" x2="21" y2="3"/><polyline points="21 16 21 21 16 21"/><line x1="15" y1="15" x2="21" y2="21"/><line x1="4" y1="4" x2="9" y2="9"/></svg></div>'+
            '<div class="fd-op-tool" title="Delete" onclick="fdDeleteOp('+op.id+')"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg></div>'+
            '<div class="fd-op-tool" title="Open in editor"><svg viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg></div>'+
          '</div>'+
        '</div>';

      // Inline config panel for selected external operation
      if(sel && isExt && conn){
        html += fdRenderOpConfig(op, conn);
      }
    });

    // After last op (or if no ops): show the "+ chooser"
    if(s.selectedOpId || s.operations.length===0){
      html += ''+
        '<div class="fd-add-chooser">'+
          '<div class="fd-add-x" title="Cancel" onclick="fdCancelChooser()"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></div>'+
          '<button class="fd-add-chip" onclick="fdOpenOpPicker()"><svg viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg>Operation</button>'+
          '<button class="fd-add-chip" onclick="fdAddOpQuick(\'Conditional Logic\')"><svg viewBox="0 0 24 24"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>Conditional Logic</button>'+
          '<button class="fd-add-chip" onclick="fdAddOpQuick(\'Nested Flow\')"><svg viewBox="0 0 24 24"><circle cx="6" cy="6" r="3"/><circle cx="18" cy="18" r="3"/><path d="M9 6h6a3 3 0 0 1 3 3v6"/></svg>Nested Flow</button>'+
        '</div>';
    } else {
      html += ''+
        '<div style="padding:8px 22px 18px 60px">'+
          '<button class="fd-add-empty" onclick="fdEnableChooser()">'+
            '<span class="fd-add-empty-plus"><svg viewBox="0 0 24 24"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></span>'+
            'Add an Operation, Conditional Logic or Nested Flow'+
          '</button>'+
        '</div>';
    }

    zone.innerHTML = html;
  }

  function fdRenderOpConfig(op, conn){
    var cfg = op.config || {};
    var headersRows = '';
    var headerKeys = Object.keys(cfg.headers || {});
    if(headerKeys.length===0) headerKeys = [''];
    headerKeys.forEach(function(k, i){
      headersRows += ''+
        '<tr>'+
          '<td><input type="text" placeholder="Header name" value="'+fdEsc(k)+'" onchange="fdUpdateOpHeader('+op.id+','+i+',\'key\',this.value)"/></td>'+
          '<td><input type="text" placeholder="Value" value="'+fdEsc((cfg.headers||{})[k]||'')+'" onchange="fdUpdateOpHeader('+op.id+','+i+',\'val\',this.value)"/></td>'+
        '</tr>';
    });

    return ''+
      '<div class="fd-op-config" onclick="event.stopPropagation()">'+
        '<div class="fd-op-config-head">'+
          '<div class="fd-conn-logo '+fdConnLogoClass(conn.type)+'">'+fdConnLogoSvg(conn.type)+'</div>'+
          '<div>Configure call to <strong>'+fdEsc(conn.name)+'</strong> — '+fdEsc(op.actionLabel||op.name)+'</div>'+
        '</div>'+

        '<div class="fd-form-row">'+
          '<div class="fd-form-group">'+
            '<div class="fd-form-label">Connection</div>'+
            '<select class="fd-form-select" onchange="fdSwitchOpConnection('+op.id+',this.value)">'+
              fdConnections.map(function(c){
                return '<option value="'+c.id+'"'+(c.id===conn.id?' selected':'')+'>'+fdEsc(c.name)+' ('+fdEsc(c.type)+')</option>';
              }).join('')+
            '</select>'+
          '</div>'+
          '<div class="fd-form-group">'+
            '<div class="fd-form-label">Action</div>'+
            '<select class="fd-form-select" onchange="fdSwitchOpAction('+op.id+',this.value)">'+
              (conn.actions||[]).map(function(a){
                return '<option value="'+a.id+'"'+(a.id===op.actionId?' selected':'')+'>'+fdEsc(a.method)+' — '+fdEsc(a.label)+'</option>';
              }).join('')+
            '</select>'+
          '</div>'+
        '</div>'+

        '<div class="fd-form-row">'+
          '<div class="fd-form-group">'+
            '<div class="fd-form-label">HTTP Method</div>'+
            '<input type="text" class="fd-form-input" value="'+fdEsc(op.actionMethod||'')+'" readonly style="background:rgba(0,0,0,0.03);font-family:var(--font-family-mono);letter-spacing:0.4px"/>'+
          '</div>'+
          '<div class="fd-form-group">'+
            '<div class="fd-form-label">Endpoint Path</div>'+
            '<input type="text" class="fd-form-input" value="'+fdEsc(op.actionPath||'')+'" onchange="fdUpdateOpField('+op.id+',\'actionPath\',this.value)" style="font-family:var(--font-family-mono)"/>'+
          '</div>'+
        '</div>'+

        '<div class="fd-form-group">'+
          '<div class="fd-form-label">Request Body (JSON)</div>'+
          '<textarea class="fd-form-textarea" placeholder=\'{"title":"{{trigger.record.name}}","priority":"high"}\' onchange="fdUpdateOpField('+op.id+',\'body\',this.value)">'+fdEsc(cfg.body||'')+'</textarea>'+
          '<div class="fd-form-help">Use <code>{{trigger.record.field}}</code> or <code>{{vars.varName}}</code> to inject flow data into the request.</div>'+
        '</div>'+

        '<div class="fd-form-group">'+
          '<div class="fd-form-label">Custom Headers <span style="font-weight:400;text-transform:none;letter-spacing:0;color:var(--txt-muted)">(merged with connection defaults)</span></div>'+
          '<table class="fd-kv-table"><tbody>'+headersRows+'</tbody></table>'+
        '</div>'+

        '<div class="fd-op-config-tip">'+
          '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>'+
          'On failure, this step\'s response will be available downstream as <code>'+fdEsc(op.name)+'.error</code>. Successful responses are exposed as <code>'+fdEsc(op.name)+'.result</code>.'+
        '</div>'+

        '<div class="fd-op-config-foot">'+
          '<button class="fd-btn" onclick="fdTestOperation('+op.id+',this)">'+
            '<svg viewBox="0 0 24 24"><polygon points="5 3 19 12 5 21 5 3"/></svg>'+
            'Test This Step'+
          '</button>'+
          '<button class="fd-btn fd-btn-primary" onclick="fdSaveOpConfig('+op.id+')">'+
            '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>'+
            'Apply'+
          '</button>'+
        '</div>'+
      '</div>';
  }

  function fdSelectOp(id){
    fdEditorState.selectedOpId = id;
    fdRenderOps();
  }
  function fdEnableChooser(){
    if(fdEditorState.operations.length===0){
      fdEditorState.selectedOpId = -1;
    }
    fdRenderOps();
  }
  function fdCancelChooser(){
    fdEditorState.selectedOpId = null;
    fdRenderOps();
  }

  // Quick-add (Conditional Logic / Nested Flow — no picker needed)
  function fdAddOpQuick(type){
    var defaultName = type==='Conditional Logic' ? 'If / Else Branch' : 'Run Nested Flow';
    var op = { id: Date.now()+Math.floor(Math.random()*1000), name: defaultName, type: type, kind:'builtin' };
    fdEditorState.operations.push(op);
    fdEditorState.selectedOpId = op.id;
    fdRenderOps();
    fdRenderDataPanel();
  }
  function fdDuplicateOp(id){
    var op = fdEditorState.operations.find(function(o){return o.id===id;}); if(!op) return;
    var copy = { id: Date.now()+Math.floor(Math.random()*1000), name: op.name+' (copy)', type: op.type };
    var idx = fdEditorState.operations.findIndex(function(o){return o.id===id;});
    fdEditorState.operations.splice(idx+1, 0, copy);
    fdEditorState.selectedOpId = copy.id;
    fdRenderOps();
    fdRenderDataPanel();
  }
  function fdDeleteOp(id){
    fdEditorState.operations = fdEditorState.operations.filter(function(o){return o.id!==id;});
    if(fdEditorState.selectedOpId===id) fdEditorState.selectedOpId = null;
    fdRenderOps();
    fdRenderDataPanel();
  }

  function fdToggleRecovery(cb){
    fdEditorState.recovery = !!cb.checked;
  }

  // ── Right-side Data panel ───────────────────────
  function fdRenderDataPanel(){
    var s = fdEditorState;
    var lbl = document.getElementById('fdDataTrigLabel');
    var pills = document.getElementById('fdDataTrigPills');
    if(lbl && pills){
      if(s.triggerCat && s.triggerOption){
        var catLbl = (fdTriggerCatalog[s.triggerCat]||{}).label || '';
        lbl.textContent = 'Initiator — '+catLbl+': '+s.triggerOption;
        var contextPills = '';
        if(s.triggerCat==='schedule'){
          contextPills =
            '<div class="fd-data-pill"><span>Run Start Date/Time</span><span class="fd-data-pill-type">Date/Time</span></div>'+
            '<div class="fd-data-pill"><span>Run Start Time UTC</span><span class="fd-data-pill-type">Date/Time</span></div>';
        } else if(s.triggerCat==='record'){
          contextPills =
            '<div class="fd-data-pill"><span>Record</span><span class="fd-data-pill-type">Record</span></div>'+
            '<div class="fd-data-pill"><span>Table</span><span class="fd-data-pill-type">Table</span></div>'+
            '<div class="fd-data-pill"><span>Operation</span><span class="fd-data-pill-type">String</span></div>';
        } else {
          contextPills =
            '<div class="fd-data-pill"><span>Event Payload</span><span class="fd-data-pill-type">Object</span></div>'+
            '<div class="fd-data-pill"><span>Source Module</span><span class="fd-data-pill-type">String</span></div>';
        }
        pills.innerHTML = contextPills;
      } else {
        lbl.textContent = 'Initiator — (none)';
        pills.innerHTML = '<div class="fd-data-pill" style="opacity:0.55;cursor:default"><span>Configure an initiator first</span></div>';
      }
    }

    var ops = document.getElementById('fdDataOpsPills');
    if(ops){
      if(s.operations.length===0){
        ops.innerHTML = '<div class="fd-data-pill" style="opacity:0.55;cursor:default"><span>Add operations to see their outputs</span></div>';
      } else {
        ops.innerHTML = s.operations.map(function(o, i){
          return ''+
            '<div class="fd-data-pill"><span>'+(i+1)+' · '+fdEsc(o.name)+' Status</span><span class="fd-data-pill-type">Choice</span></div>'+
            '<div class="fd-data-pill"><span>'+(i+1)+' · '+fdEsc(o.name)+' Result</span><span class="fd-data-pill-type">Object</span></div>';
        }).join('');
      }
    }
  }

  function fdToggleGroup(id){
    var el = document.getElementById(id);
    if(el) el.classList.toggle('collapsed');
  }
  function fdToggleAllGroups(expand){
    ['fdGrpVars','fdGrpTrigger','fdGrpOps'].forEach(function(g){
      var el = document.getElementById(g);
      if(!el) return;
      if(expand) el.classList.remove('collapsed');
      else       el.classList.add('collapsed');
    });
  }

  function fdRunTest(){
    if(!fdEditorState.triggerCat){ alert('Please configure an Initiator before running a test.'); return; }
    // For the Well Delay Remediation flows, run the same staged execution but in test mode
    if(fdEditorState.flowId === 11 || fdEditorState.flowId === 12){
      fdExecutePublishFlow(true);
      return;
    }
    if(fdEditorState.flowId === 13){
      fdExecuteRPAFlow(true);
      return;
    }
    alert('Test run triggered. Check the Run History tab for results.');
  }
  function fdPublish(btn){
    if(!fdEditorState.triggerCat){ alert('Cannot publish — please configure an Initiator first.'); return; }
    if(fdEditorState.operations.length===0){ alert('Cannot publish — please add at least one Operation.'); return; }

    // RPA flow has its own bot-style executor with file upload
    if(fdEditorState.flowId === 13){
      fdExecuteRPAFlow(false);
      return;
    }

    // Detect if this flow contains a real (LIVE) operation
    var hasLiveOp = fdEditorState.operations.some(function(op){
      return op.isReal === true ||
             (op.kind==='external' && fdConnections.find(function(c){return c.id===op.connectionId && c.isReal;}));
    });

    if(hasLiveOp){
      // Animated stepwise publish with real ServiceNow call
      fdExecutePublishFlow(false);
      return;
    }

    // ── Standard (mock) publish path ──
    fdEditorState.status = 'published';
    var chip = document.getElementById('fdStatusChip');
    if(chip){ chip.textContent='Published'; chip.classList.add('published'); }
    var isFormFlow = fdEditorState.triggerCat === 'record' && fdEditorState.triggerOption === 'On Catalogue Submit';
    if(fdEditorState.flowId){
      var f = fdFlows.find(function(x){return x.id===fdEditorState.flowId;});
      if(f){
        f.name = fdEditorState.flowName;
        f.status = 'published';
        f.trigger = fdEditorState.triggerCat;
        f.triggerLabel = fdEditorState.triggerSummaryOverride || ((fdTriggerCatalog[fdEditorState.triggerCat]||{}).label+' · '+fdEditorState.triggerOption);
        f.modified = new Date().toISOString().slice(0,10);
        if(isFormFlow){
          f.isFormFlow = true;
          f.formId   = fdEditorState.triggerFormId || null;
          f.formName = fdEditorState.triggerFormName || null;
        }
      }
    } else {
      var newId = (fdFlows.length ? Math.max.apply(null, fdFlows.map(function(x){return x.id;})) : 0) + 1;
      var newFlow = {
        id: newId,
        name: fdEditorState.flowName,
        status: 'published',
        trigger: fdEditorState.triggerCat,
        triggerLabel: fdEditorState.triggerSummaryOverride || ((fdTriggerCatalog[fdEditorState.triggerCat]||{}).label+' · '+fdEditorState.triggerOption),
        desc: 'Newly created flow.',
        modified: new Date().toISOString().slice(0,10),
        lastRun: '—',
        owner: 'You'
      };
      if(isFormFlow){
        newFlow.isFormFlow = true;
        newFlow.formId   = fdEditorState.triggerFormId || null;
        newFlow.formName = fdEditorState.triggerFormName || null;
      }
      fdFlows.unshift(newFlow);
      fdEditorState.flowId = newId;
    }
    alert('Flow published successfully.');
  }

  // ── Live publish flow (animated stepwise execution) ──
  // Walks each operation in the flow, mocks the data ones, makes the real
  // HTTP call for any operation flagged isReal:true. Currently the only real
  // call is the ServiceNow incident creation at the end of "Well Delay Remediation".
  function fdClosePubModal(){ document.getElementById('fdPubModal').classList.remove('open'); }
  function fdMaybeClosePub(e){ if(e.target.id==='fdPubModal') fdClosePubModal(); }

  // Mock data the workflow generates as it runs — referenced when building the
  // ServiceNow incident body so the real ticket has realistic content.
  var fdRemediationMockData = {
    activeWells: ['GNR-2221','GSNR-3341','AMIN-274','GNR-1702','GSNR-4082'],
    delayedWell: null,        // populated after agent step
    extraWorkers: 0,          // populated after AI suggestion
    crewSelected: null        // populated after crew filter
  };

  function fdExecutePublishFlow(isTestRun){
    var modal = document.getElementById('fdPubModal');
    var body  = document.getElementById('fdPubBody');
    var title = document.getElementById('fdPubTitle');
    var sub   = document.getElementById('fdPubSubtitle');
    var closeBtn = document.getElementById('fdPubClose');
    var doneBtn  = document.getElementById('fdPubDoneBtn');

    title.textContent = (isTestRun ? 'Running Test — ' : 'Publishing — ') + fdEditorState.flowName;
    sub.textContent = 'Executing each operation in sequence. The final step makes a real HTTP request to ServiceNow.';
    body.innerHTML = '';
    closeBtn.style.display = 'none';
    doneBtn.style.display = 'none';
    modal.classList.add('open');

    var ops = fdEditorState.operations;

    function runStep(idx){
      if(idx >= ops.length){
        finishUp(true);
        return;
      }
      var op = ops[idx];
      var isLive = op.isReal === true ||
                   (op.kind==='external' && fdConnections.find(function(c){return c.id===op.connectionId && c.isReal;}));

      // Render pending step
      var stepEl = document.createElement('div');
      stepEl.className = 'fd-pub-step pending' + (isLive?' live':'');
      stepEl.innerHTML = ''+
        '<div class="fd-pub-step-icon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg></div>'+
        '<div class="fd-pub-step-info">'+
          '<div class="fd-pub-step-name">Step '+(idx+1)+': '+fdEsc(op.name)+(isLive?'<span class="fd-pub-live-tag">LIVE</span>':'')+'</div>'+
          '<div class="fd-pub-step-detail">'+fdEsc(op.desc||'Executing…')+'</div>'+
        '</div>';
      body.appendChild(stepEl);
      body.scrollTop = body.scrollHeight;

      if(isLive){
        // ── Detect REST vs UI automation ──
        var conn = fdConnections.find(function(c){return c.id===op.connectionId;});
        var isUIAuto = (op.isUI === true) || (conn && conn.type === 'ServiceNow UI');

        // Re-tag the step as UI-automation if applicable
        if(isUIAuto){
          stepEl.classList.remove('live'); stepEl.classList.add('uiauto');
          var nameSpan = stepEl.querySelector('.fd-pub-step-name');
          if(nameSpan) nameSpan.innerHTML = 'Step '+(idx+1)+': '+fdEsc(op.name)+'<span class="fd-pub-uiauto-tag">UI AUTOMATION</span>';
        }

        if(isUIAuto){
          // ── Browser UI automation path (Selenium / Playwright) ──
          fdUIAutomationCall(op, stepEl, function(){
            setTimeout(function(){ runStep(idx+1); }, 300);
          });
          return;
        }

        // ── REAL ServiceNow REST incident creation ──
        fdLiveServiceNowCall(op, function(result){
          var infoBox = stepEl.querySelector('.fd-pub-step-info');
          stepEl.classList.remove('pending');
          if(result.ok){
            stepEl.classList.add('success');
            stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>';
            infoBox.innerHTML += '<div class="fd-pub-step-meta">POST '+fdEsc(result.url)+' → HTTP '+result.status+' in '+result.ms+' ms</div>';
            infoBox.innerHTML += ''+
              '<div class="fd-pub-incident-card">'+
                '<div class="fd-pub-incident-head">'+
                  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><polyline points="20 6 9 17 4 12"/></svg>'+
                  'Real ServiceNow incident created · <span class="fd-pub-incident-num">'+fdEsc(result.number)+'</span>'+
                '</div>'+
                '<div style="font-size:9pt;color:var(--txt-2);line-height:1.5">'+fdEsc(result.shortDescription)+'</div>'+
                '<a class="fd-pub-incident-link" onclick="window.open(\''+fdEsc(result.viewUrl)+'\',\'_blank\')">'+
                  '<svg viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>'+
                  'Open in ServiceNow ('+fdEsc(result.viewUrl)+')'+
                '</a>'+
              '</div>';
          } else {
            stepEl.classList.add('error');
            stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>';
            infoBox.innerHTML += ''+
              '<div class="fd-pub-incident-card fail">'+
                '<div class="fd-pub-incident-head">'+
                  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/></svg>'+
                  'Live call failed · '+fdEsc(result.errorTitle)+
                '</div>'+
                '<div style="font-size:9pt;color:var(--txt-2);line-height:1.5">'+result.errorDetail+'</div>'+
                '<div style="font-size:9pt;color:var(--txt-muted);margin-top:8px">Run this from your terminal to verify the integration works without the browser-CORS hurdle:</div>'+
                '<div class="fd-pub-curl">'+fdEsc(result.curl)+'</div>'+
              '</div>';
          }
          body.scrollTop = body.scrollHeight;
          // Continue regardless of success — flow still publishes
          setTimeout(function(){ runStep(idx+1); }, 300);
        });
      } else {
        // ── Mock step — simulate processing time and update mock data ──
        var simMs = 400 + Math.random()*500;
        setTimeout(function(){
          stepEl.classList.remove('pending');
          stepEl.classList.add('success');
          stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>';

          // Generate plausible mock output for this step
          var meta = '';
          if(op.category === 'data-query' && /vise/i.test(op.name)){
            meta = 'Returned '+fdRemediationMockData.activeWells.length+' active wells: '+fdRemediationMockData.activeWells.join(', ');
          } else if(op.category === 'agent-call'){
            // Simulate calling Well Delay Predictor for each well — pick the first delayed one
            fdRemediationMockData.delayedWell = { well_id:'GNR-2221', will_be_delayed:true, estimated_delay_days:8, confidence:0.86 };
            meta = 'Agent processed 5 wells. Result for GNR-2221 → will_be_delayed=true, est_delay=8d, confidence=0.86';
          } else if(op.category === 'filter' && /will_be_delayed/i.test(op.name)){
            meta = 'Kept 2 of 5 wells: GNR-2221 (8d, 0.86), AMIN-274 (12d, 0.78). Discarded 3 on-track wells.';
          } else if(op.category === 'ai-suggest'){
            fdRemediationMockData.extraWorkers = 4;
            meta = 'AI suggestion: add 4 additional workers for ~2.1 days of velocity recovery. Justification: required_velocity gap = 0.54 %/day; historical recovery factor = 0.13 %/day per worker.';
          } else if(op.category === 'data-query' && /calendar/i.test(op.name)){
            meta = 'Crew calendar returned 12 crews. 8 allocated, 4 unallocated.';
          } else if(op.category === 'filter' && /allocation/i.test(op.name)){
            fdRemediationMockData.crewSelected = { crew_id:'CRW-007', leader:'F. Al-Hamdi', headcount:6 };
            meta = 'Selected unallocated crew CRW-007 (lead: F. Al-Hamdi, 6 workers available). 3 other unallocated crews kept on standby.';
          } else {
            meta = 'Completed in '+Math.round(simMs)+' ms.';
          }
          stepEl.querySelector('.fd-pub-step-info').innerHTML += '<div class="fd-pub-step-meta">'+fdEsc(meta)+'</div>';
          body.scrollTop = body.scrollHeight;
          runStep(idx+1);
        }, simMs);
      }
    }

    function finishUp(ok){
      closeBtn.style.display = '';
      doneBtn.style.display = '';
      if(!isTestRun){
        // Mark flow published
        fdEditorState.status = 'published';
        var chip = document.getElementById('fdStatusChip');
        if(chip){ chip.textContent='Published'; chip.classList.add('published'); }
        if(fdEditorState.flowId){
          var f = fdFlows.find(function(x){return x.id===fdEditorState.flowId;});
          if(f){
            f.status = 'published';
            f.lastRun = new Date().toISOString().replace('T',' ').slice(0,16);
            f.modified = new Date().toISOString().slice(0,10);
          }
        }
        title.textContent = '✓ Workflow Published';
        sub.textContent = 'All operations executed. The flow is now live and will run on its configured schedule.';
      } else {
        title.textContent = '✓ Test Run Complete';
        sub.textContent = 'All operations executed. Workflow is still in '+fdEditorState.status+' state.';
      }
    }

    // Kick off
    runStep(0);
  }

  // Make the real ServiceNow incident POST. Substitutes mock workflow
  // data into the body template, then calls fetch with Basic Auth.
  function fdLiveServiceNowCall(op, done){
    var conn = fdConnections.find(function(c){return c.id===op.connectionId;});
    if(!conn){ return done({ ok:false, errorTitle:'Connection missing', errorDetail:'The ServiceNow connection has been deleted.', curl:'' }); }

    var url = conn.baseUrl.replace(/\/+$/,'') + op.actionPath;
    var bodyTemplate = (op.config && op.config.body) || '{}';
    // Substitute mock data into template placeholders
    var d = fdRemediationMockData;
    var body = bodyTemplate
      .replace(/\{\{well_id\}\}/g, (d.delayedWell && d.delayedWell.well_id) || 'UNKNOWN')
      .replace(/\{\{estimated_delay_days\}\}/g, (d.delayedWell && d.delayedWell.estimated_delay_days) || '?')
      .replace(/\{\{confidence\}\}/g, (d.delayedWell && d.delayedWell.confidence) || '?')
      .replace(/\{\{extra_workers\}\}/g, d.extraWorkers || '?')
      .replace(/\{\{crew_id\}\}/g, (d.crewSelected && d.crewSelected.crew_id) || 'UNKNOWN');

    // Build curl for the fallback display
    var curl = "curl -u '"+conn.authUsername+":"+conn.authPassword+"' \\\n"+
               "  -H 'Content-Type: application/json' \\\n"+
               "  -H 'Accept: application/json' \\\n"+
               "  -X POST '"+url+"' \\\n"+
               "  -d '"+body.replace(/\n/g,'').replace(/'/g,"'\\''")+"'";

    var startedAt = Date.now();
    fetch(url, {
      method:'POST',
      headers:{
        'Authorization':'Basic ' + btoa(conn.authUsername+':'+conn.authPassword),
        'Content-Type':'application/json',
        'Accept':'application/json'
      },
      body: body
    }).then(function(res){
      var ms = Date.now()-startedAt;
      if(res.ok){
        return res.json().then(function(d2){
          var rec = d2.result || {};
          var instance = conn.baseUrl.replace(/\/+$/,'');
          var viewUrl = instance + '/nav_to.do?uri=incident.do?sys_id=' + (rec.sys_id || '');
          done({
            ok:true, status:res.status, ms:ms, url:url,
            number: rec.number || '(no number returned)',
            shortDescription: rec.short_description || '(no description returned)',
            viewUrl: viewUrl
          });
        });
      } else {
        return res.text().then(function(t){
          done({
            ok:false, status:res.status,
            errorTitle:'HTTP '+res.status+' '+res.statusText,
            errorDetail:'<code style="background:rgba(255,0,0,0.08);padding:2px 6px;border-radius:3px;font-family:var(--font-family-mono);font-size:9pt">'+fdEsc(t.slice(0,300))+'</code>',
            curl: curl
          });
        });
      }
    }).catch(function(err){
      done({
        ok:false,
        errorTitle:'Browser blocked the request (CORS or network)',
        errorDetail:'<strong>'+fdEsc(err.message||'fetch failed')+'</strong><br>'+
          'ServiceNow rejected the cross-origin request from this page. To make the LIVE call succeed:<br>'+
          '1. In ServiceNow, open <code>System Web Services → REST → CORS Rules</code><br>'+
          '2. Add a rule for the page origin (use <code>file://</code> or your dev host) and allow <code>POST</code> on the <code>incident</code> table endpoint.<br>'+
          '3. Re-publish.',
        curl: curl
      });
    });
  }

  // ═══════════ UI AUTOMATION (Selenium/Playwright) ═══════════
  // Browsers cannot drive Selenium/Playwright directly — those tools run
  // server-side. From the page we do three things instead:
  //   1. Animate the simulated automation steps so the workflow visually
  //      shows what real automation would do
  //   2. Open ServiceNow in a popup with the new-incident form pre-populated
  //      via URL parameters so the user can verify and submit manually
  //   3. Generate ready-to-run Selenium Python and Playwright TypeScript
  //      scripts the user can copy and run from their terminal
  function fdUIAutomationCall(op, stepEl, doneCb){
    var conn = fdConnections.find(function(c){return c.id===op.connectionId;});
    if(!conn){ return doneCb(); }

    // Substitute mock workflow data into the body template
    var bodyTemplate = (op.config && op.config.body) || '{}';
    var d = fdRemediationMockData;
    var bodyStr = bodyTemplate
      .replace(/\{\{well_id\}\}/g, (d.delayedWell && d.delayedWell.well_id) || 'UNKNOWN')
      .replace(/\{\{estimated_delay_days\}\}/g, (d.delayedWell && d.delayedWell.estimated_delay_days) || '?')
      .replace(/\{\{confidence\}\}/g, (d.delayedWell && d.delayedWell.confidence) || '?')
      .replace(/\{\{extra_workers\}\}/g, d.extraWorkers || '?')
      .replace(/\{\{crew_id\}\}/g, (d.crewSelected && d.crewSelected.crew_id) || 'UNKNOWN');
    var fields;
    try { fields = JSON.parse(bodyStr); }
    catch(e){ fields = { short_description: 'Workflow ticket', description: bodyStr, urgency:'2', impact:'2' }; }

    var infoBox = stepEl.querySelector('.fd-pub-step-info');
    // Inline status under step name
    var status = document.createElement('div');
    status.style.cssText = 'margin-top:8px;font-size:9pt;color:#00B0F0;font-weight:500;display:flex;align-items:center;gap:7px';
    status.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:13px;height:13px"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Launching Selenium-driven Chrome browser… (watch the simulator)';
    infoBox.appendChild(status);

    // Launch the visual browser simulator
    fdLaunchVisualBrowser(conn, op, fields, function(result){
      // Mark step success
      stepEl.classList.remove('pending');
      stepEl.classList.add('success');
      stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>';

      // Update inline status
      status.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:13px;height:13px"><polyline points="20 6 9 17 4 12"/></svg>Selenium automation completed · simulated incident <strong style="font-family:var(--font-family-mono)">'+result.number+'</strong>';

      // Build pre-filled URL for actual ticket creation
      var query = ['short_description='+(fields.short_description||''),
                   'description='+(fields.description||''),
                   'urgency='+(fields.urgency||'2'),
                   'impact='+(fields.impact||'2')]
                   .map(function(p){ var i=p.indexOf('='); return p.slice(0,i+1)+encodeURIComponent(p.slice(i+1)); })
                   .join('^');
      var prefilledUrl = conn.baseUrl.replace(/\/+$/,'') + '/incident.do?sys_id=-1&sysparm_query=' + query;

      var seleniumScript = fdGenSeleniumScript(conn, op, fields);
      var playwrightScript = fdGenPlaywrightScript(conn, op, fields);
      var cardId = 'snowui_'+Date.now();

      var card = document.createElement('div');
      card.className = 'fd-pub-uiauto-card';
      card.innerHTML = ''+
        '<div class="fd-pub-uiauto-head">'+
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><rect x="3" y="3" width="18" height="14" rx="2"/><line x1="3" y1="8" x2="21" y2="8"/><polygon points="13 14 13 21 15 19 16.5 21 18 20 16.5 18 18.5 17.5"/></svg>'+
          'UI Automation Sequence Complete · '+
          '<span style="font-family:var(--font-family-mono);background:#D6E4F0;color:#2E75B6;padding:2px 8px;border-radius:4px;border:1px solid #2E75B6;margin-left:4px">'+result.number+'</span>'+
        '</div>'+
        '<div style="font-size:10pt;color:var(--txt-2);line-height:1.55;margin-bottom:6px">'+
          'You watched the Selenium driver navigate to ServiceNow, log in, fill the incident form and submit it. <strong>Note:</strong> the simulator runs entirely inside this page and does not produce a real ServiceNow record (browsers cannot execute Selenium). To actually create the ticket on '+conn.baseUrl.replace(/^https?:\/\//,'')+', use one of the options below:'+
        '</div>'+

        '<div class="fd-pub-uiauto-actions">'+
          '<button class="fd-pub-uiauto-btn primary" onclick="fdReplayVisualBrowser('+conn.id+',\''+fdEsc(op.id+'').replace(/\'/g,"\\\\'")+'\')">'+
            '<svg viewBox="0 0 24 24"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>'+
            'Replay Automation'+
          '</button>'+
          '<button class="fd-pub-uiauto-btn primary" onclick="fdOpenSnowPrefilled(\''+fdEsc(prefilledUrl).replace(/\'/g,"\\\\'")+'\')" style="background:linear-gradient(135deg,#2E75B6,#1F3864)">'+
            '<svg viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>'+
            'Create Real Ticket Now (pre-filled)'+
          '</button>'+
          '<button class="fd-pub-uiauto-btn secondary" onclick="fdDownloadScript(\''+cardId+'\')">'+
            '<svg viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>'+
            'Download Script'+
          '</button>'+
        '</div>'+

        '<div style="font-size:9pt;color:var(--txt-muted);margin-top:10px;line-height:1.5">'+
          '<strong>"Create Real Ticket Now"</strong> opens ServiceNow in a new tab with the form pre-populated from this workflow run. Log in once, click Submit. Form fields you would see in the URL:'+
        '</div>'+
        '<div class="fd-pub-url-preview"><span class="url-key">'+conn.baseUrl.replace(/\/+$/,'')+'</span><span class="url-val">/incident.do?sys_id=-1&sysparm_query='+fdEsc(query.slice(0,200))+(query.length>200?'…':'')+'</span></div>'+

        '<div class="fd-script-viewer" id="'+cardId+'">'+
          '<div class="fd-script-tabs">'+
            '<button class="fd-script-tab active" data-pane="sel" onclick="fdSwitchScript(\''+cardId+'\',\'sel\')">'+
              '<svg viewBox="0 0 24 24"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>'+
              'Real Selenium Script (Python)'+
            '</button>'+
            '<button class="fd-script-tab" data-pane="pw" onclick="fdSwitchScript(\''+cardId+'\',\'pw\')">'+
              '<svg viewBox="0 0 24 24"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>'+
              'Real Playwright Script (TypeScript)'+
            '</button>'+
            '<div class="fd-script-actions">'+
              '<button class="fd-script-copy" onclick="fdCopyScript(this,\''+cardId+'\')">'+
                '<svg viewBox="0 0 24 24"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>'+
                'Copy'+
              '</button>'+
            '</div>'+
          '</div>'+
          '<div class="fd-script-pane active" data-pane="sel"><pre class="fd-script-code">'+fdSyntaxHighlightPython(seleniumScript)+'</pre></div>'+
          '<div class="fd-script-pane" data-pane="pw"><pre class="fd-script-code">'+fdSyntaxHighlightTS(playwrightScript)+'</pre></div>'+
        '</div>'+

        '<div style="font-size:9pt;color:var(--txt-muted);margin-top:10px;line-height:1.5">'+
          'Run the script for a real, automated ticket creation: <code style="font-family:var(--font-family-mono);background:rgba(0,176,240,0.08);padding:1px 5px;border-radius:3px">pip install selenium webdriver-manager &amp;&amp; python create_snow_incident.py</code>. The script does exactly what the simulator just showed you — opens Chrome, logs in, fills the form, submits — and creates a real ticket on '+conn.baseUrl.replace(/^https?:\/\//,'')+'.'+
        '</div>';
      infoBox.appendChild(card);

      card._seleniumScript = seleniumScript;
      card._playwrightScript = playwrightScript;
      card._prefilledUrl = prefilledUrl;
      // Stash for replay
      card._connId = conn.id;
      card._opData = op;
      card._fields = fields;

      var body = document.getElementById('fdPubBody');
      if(body) body.scrollTop = body.scrollHeight;

      doneCb();
    });
  }

  // Replays the visual browser without re-running the whole workflow
  function fdReplayVisualBrowser(connId, opIdStr){
    var conn = fdConnections.find(function(c){return c.id===connId;}); if(!conn) return;
    // Find the most recent matching card to get the fields used
    var cards = document.querySelectorAll('.fd-pub-uiauto-card');
    var card = cards[cards.length-1];
    if(!card || !card._fields) return;
    fdLaunchVisualBrowser(conn, card._opData, card._fields, function(){});
  }

