                                                                  cursor.style.opacity = '0.3';
                                                                  autLog('ok',     '[201] Record saved.');
                                                                  autLog('result', '[result] Incident '+mockNum+' created. driver.quit()');
                                                                  closeBtn.classList.add('show');
