  function fdSwitchScript(cardId, pane){
    var card = document.getElementById(cardId);
    if(!card) return;
    card.querySelectorAll('.fd-script-tab').forEach(function(t){ t.classList.toggle('active', t.getAttribute('data-pane')===pane); });
    card.querySelectorAll('.fd-script-pane').forEach(function(p){ p.classList.toggle('active', p.getAttribute('data-pane')===pane); });
  }

  function fdCopyScript(btn, cardId){
    var card = document.getElementById(cardId);
    if(!card) return;
    var activePane = card.querySelector('.fd-script-tab.active').getAttribute('data-pane');
    var script = activePane==='sel' ? card._seleniumScript : card._playwrightScript;
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(script).then(function(){
        var orig = btn.innerHTML;
        btn.classList.add('copied');
        btn.innerHTML = '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>Copied!';
        setTimeout(function(){ btn.classList.remove('copied'); btn.innerHTML = orig; }, 1800);
      });
    } else {
      // Fallback
      var ta = document.createElement('textarea'); ta.value = script; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); } catch(e){}
      document.body.removeChild(ta);
    }
  }

  function fdDownloadScript(cardId){
    var card = document.getElementById(cardId);
    if(!card) return;
    var activePane = card.querySelector('.fd-script-tab.active').getAttribute('data-pane');
    var script = activePane==='sel' ? card._seleniumScript : card._playwrightScript;
    var filename = activePane==='sel' ? 'create_snow_incident.py' : 'create_snow_incident.ts';
    var blob = new Blob([script], { type:'text/plain' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 100);
  }

  function fdGenSeleniumScript(conn, op, fields){
    return ''+
'#!/usr/bin/env python3\n'+
'"""\n'+
'Auto-generated by Al Tasnim Process Automation — Well Delay Remediation (UI Connector)\n'+
'\n'+
'Drives the ServiceNow web UI to log in and create an Incident from workflow data.\n'+
'Mirrors the steps the workflow simulated in the browser.\n'+
'\n'+
'Requirements:\n'+
'  pip install selenium webdriver-manager\n'+
'\n'+
'Usage:\n'+
'  python create_snow_incident.py\n'+
'"""\n'+
'from selenium import webdriver\n'+
'from selenium.webdriver.common.by import By\n'+
'from selenium.webdriver.support.ui import WebDriverWait, Select\n'+
'from selenium.webdriver.support import expected_conditions as EC\n'+
'from selenium.webdriver.chrome.options import Options\n'+
'from webdriver_manager.chrome import ChromeDriverManager\n'+
'from selenium.webdriver.chrome.service import Service\n'+
'\n'+
'# ── Configuration ─────────────────────────────────────────────\n'+
'INSTANCE = "'+conn.baseUrl+'"\n'+
'USERNAME = "'+conn.authUsername+'"\n'+
'PASSWORD = "'+conn.authPassword+'"\n'+
'\n'+
'INCIDENT = {\n'+
'    "short_description": "'+(fields.short_description||'').replace(/"/g,'\\"')+'",\n'+
'    "description":       """'+(fields.description||'').replace(/"""/g,'""')+'""",\n'+
'    "urgency":           "'+(fields.urgency||'2')+'",\n'+
'    "impact":            "'+(fields.impact||'2')+'",\n'+
'    "category":          "'+(fields.category||'inquiry')+'",\n'+
'}\n'+
'\n'+
'# ── Driver setup ──────────────────────────────────────────────\n'+
'options = Options()\n'+
'# options.add_argument("--headless=new")  # uncomment to run headless\n'+
'driver = webdriver.Chrome(service=Service(ChromeDriverManager().install()), options=options)\n'+
'wait = WebDriverWait(driver, 15)\n'+
'\n'+
'try:\n'+
'    # 1. Open login page\n'+
'    driver.get(f"{INSTANCE}/login.do")\n'+
'    print(f"[nav]    {driver.current_url}")\n'+
'\n'+
'    # 2. Authenticate\n'+
'    wait.until(EC.presence_of_element_located((By.ID, "user_name"))).send_keys(USERNAME)\n'+
'    driver.find_element(By.ID, "user_password").send_keys(PASSWORD)\n'+
'    driver.find_element(By.ID, "sysverb_login").click()\n'+
'    print(f"[ok]     Authenticated as {USERNAME}")\n'+
'\n'+
'    # 3. Wait for the post-login redirect, then navigate to the new-incident form\n'+
'    wait.until(EC.url_contains("navpage.do"))\n'+
'    driver.get(f"{INSTANCE}/incident.do?sys_id=-1")\n'+
'\n'+
'    # 4. ServiceNow renders the form inside an iframe (gsft_main in classic UI)\n'+
'    wait.until(EC.frame_to_be_available_and_switch_to_it((By.ID, "gsft_main")))\n'+
'\n'+
'    # 5. Fill the incident fields\n'+
'    short = wait.until(EC.element_to_be_clickable((By.ID, "incident.short_description")))\n'+
'    short.send_keys(INCIDENT["short_description"])\n'+
'\n'+
'    driver.find_element(By.ID, "incident.description").send_keys(INCIDENT["description"])\n'+
'\n'+
'    # Native HTML dropdown fields — use Selenium\'s Select helper\n'+
'    Select(driver.find_element(By.ID, "incident.urgency")).select_by_value(INCIDENT["urgency"])\n'+
'    Select(driver.find_element(By.ID, "incident.impact" )).select_by_value(INCIDENT["impact"])\n'+
'    Select(driver.find_element(By.ID, "incident.category")).select_by_value(INCIDENT["category"])\n'+
'\n'+
'    # 6. Submit — sysverb_insert is the standard ServiceNow form-insert button\n'+
'    driver.find_element(By.ID, "sysverb_insert").click()\n'+
'\n'+
'    # 7. After insert, ServiceNow navigates to the new record. Capture its number.\n'+
'    wait.until(EC.presence_of_element_located((By.ID, "incident.number")))\n'+
'    incident_number = driver.find_element(By.ID, "incident.number").get_attribute("value")\n'+
'    print(f"[result] Incident {incident_number} created.")\n'+
'    print(f"[url]    {driver.current_url}")\n'+
'\n'+
'finally:\n'+
'    input("Press Enter to close the browser…")\n'+
'    driver.quit()\n';
  }

  function fdGenPlaywrightScript(conn, op, fields){
    return ''+
'/**\n'+
' * Auto-generated by Al Tasnim Process Automation — Well Delay Remediation (UI Connector)\n'+
' *\n'+
' * Drives the ServiceNow web UI to log in and create an Incident from workflow data.\n'+
' *\n'+
' * Setup:\n'+
' *   npm i -D @playwright/test\n'+
' *   npx playwright install\n'+
' *\n'+
' * Run:\n'+
' *   npx playwright test create_snow_incident.ts --headed\n'+
' */\n'+
'import { test, expect } from \'@playwright/test\';\n'+
'\n'+
'const INSTANCE = \''+conn.baseUrl+'\';\n'+
'const USERNAME = \''+conn.authUsername+'\';\n'+
'const PASSWORD = \''+conn.authPassword.replace(/'/g,"\\\\'")+'\';\n'+
'\n'+
'const INCIDENT = {\n'+
'  short_description: \''+(fields.short_description||'').replace(/'/g,"\\\\'")+'\',\n'+
'  description:       `'+(fields.description||'').replace(/`/g,'\\\\`')+'`,\n'+
'  urgency:           \''+(fields.urgency||'2')+'\',\n'+
'  impact:            \''+(fields.impact||'2')+'\',\n'+
'};\n'+
'\n'+
'test(\'create ServiceNow incident via UI\', async ({ page }) => {\n'+
'  // 1. Open login page\n'+
'  await page.goto(`${INSTANCE}/login.do`);\n'+
'\n'+
'  // 2. Authenticate\n'+
'  await page.fill(\'#user_name\',     USERNAME);\n'+
'  await page.fill(\'#user_password\', PASSWORD);\n'+
'  await page.click(\'#sysverb_login\');\n'+
'  await page.waitForURL(/navpage\\.do/);\n'+
'\n'+
'  // 3. Navigate to new-incident form\n'+
'  await page.goto(`${INSTANCE}/incident.do?sys_id=-1`);\n'+
'\n'+
'  // 4. ServiceNow forms render inside the gsft_main iframe (classic UI)\n'+
'  const frame = page.frameLocator(\'#gsft_main\');\n'+
'\n'+
'  // 5. Fill the incident fields\n'+
'  await frame.locator(\'#incident\\\\.short_description\').fill(INCIDENT.short_description);\n'+
'  await frame.locator(\'#incident\\\\.description\'      ).fill(INCIDENT.description);\n'+
'  await frame.locator(\'#incident\\\\.urgency\'          ).selectOption(INCIDENT.urgency);\n'+
'  await frame.locator(\'#incident\\\\.impact\'           ).selectOption(INCIDENT.impact);\n'+
'\n'+
'  // 6. Submit\n'+
'  await frame.locator(\'#sysverb_insert\').click();\n'+
'\n'+
'  // 7. Capture the new record number\n'+
'  const numberInput = frame.locator(\'#incident\\\\.number\');\n'+
'  await expect(numberInput).toBeVisible();\n'+
'  const incidentNumber = await numberInput.inputValue();\n'+
'  console.log(`[result] Incident ${incidentNumber} created.`);\n'+
'  console.log(`[url]    ${page.url()}`);\n'+
'});\n';
  }

  // Naive syntax highlighting — colourises strings, comments, keywords
  function fdSyntaxHighlightPython(src){
    var s = fdEsc(src);
    s = s.replace(/(&#34;&#34;&#34;[\s\S]*?&#34;&#34;&#34;|&#34;[^&]*?&#34;|&#39;[^&]*?&#39;)/g, '<span class="str">$1</span>');
    s = s.replace(/(#[^\n]*)/g, '<span class="com">$1</span>');
    s = s.replace(/\b(import|from|def|class|try|finally|return|if|else|for|while|in|as|with|print|input|True|False|None|raise|pass)\b/g, '<span class="kw">$1</span>');
    return s;
  }
  function fdSyntaxHighlightTS(src){
    var s = fdEsc(src);
    s = s.replace(/(`[^`]*`|&#39;[^&]*?&#39;|&#34;[^&]*?&#34;)/g, '<span class="str">$1</span>');
    s = s.replace(/(\/\/[^\n]*|\/\*[\s\S]*?\*\/)/g, '<span class="com">$1</span>');
    s = s.replace(/\b(import|from|const|let|var|function|async|await|return|if|else|for|while|in|of|new|class|extends|test|expect|true|false|null|undefined)\b/g, '<span class="kw">$1</span>');
    return s;
  }


  // ═══════════════════════════════════════════════════════════
  // RPA EXECUTOR — Worker Incidents Bulk Import
  //
  // Real Excel reading via SheetJS, real ServiceNow REST calls per row.
  // Styled as RPA bot console (UiPath Orchestrator-style logs + queue grid).
  // ═══════════════════════════════════════════════════════════

  function fdExecuteRPAFlow(isTestRun){
    var modal = document.getElementById('fdPubModal');
    var body  = document.getElementById('fdPubBody');
    var title = document.getElementById('fdPubTitle');
    var sub   = document.getElementById('fdPubSubtitle');
    var closeBtn = document.getElementById('fdPubClose');
    var doneBtn  = document.getElementById('fdPubDoneBtn');

    title.innerHTML = (isTestRun ? 'Running Test — ' : 'Publishing — ') + fdEsc(fdEditorState.flowName) + '<span class="rpa-tag">RPA BOT</span>';
    sub.textContent = 'Unattended bot will read the Excel file you upload and create one ServiceNow incident per row via REST.';
    body.innerHTML = '';
    closeBtn.style.display = 'none';
    doneBtn.style.display = 'none';
    modal.classList.add('open');

    // RPA state
    var rpaState = {
      file: null,
      rows: [],
      validRows: [],
      results: [],
      bot: { name:'WellOps-Bot-01', license:'ATU-RPA-2026-1138' }
    };

    var ops = fdEditorState.operations;

    function runStep(idx){
      if(idx >= ops.length){ return finishUp(); }
      var op = ops[idx];
      var stepEl = document.createElement('div');
      stepEl.className = 'fd-pub-step pending';
      stepEl.innerHTML = ''+
        '<div class="fd-pub-step-icon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg></div>'+
        '<div class="fd-pub-step-info">'+
          '<div class="fd-pub-step-name">Step '+(idx+1)+': '+fdEsc(op.name)+'</div>'+
          '<div class="fd-pub-step-detail">'+fdEsc(op.desc||'Executing…')+'</div>'+
        '</div>';
      body.appendChild(stepEl);
      body.scrollTop = body.scrollHeight;

      var infoBox = stepEl.querySelector('.fd-pub-step-info');

      if(op.category === 'rpa-init'){
        setTimeout(function(){
          rpaSucceed(stepEl, '<div class="rpa-step-host"><div class="rpa-bot-row">'+
            '<div class="rpa-bot-avatar"><svg viewBox="0 0 24 24"><rect x="4" y="7" width="16" height="13" rx="2"/><path d="M9 7V4a3 3 0 0 1 6 0v3"/><circle cx="9" cy="13" r="1"/><circle cx="15" cy="13" r="1"/><path d="M9 17h6"/></svg></div>'+
            '<div class="rpa-bot-info"><div class="rpa-bot-name">'+rpaState.bot.name+'</div><div class="rpa-bot-state">Idle → Activated · ServiceNow credential acquired</div></div>'+
            '<div class="rpa-bot-license">'+rpaState.bot.license+'</div>'+
          '</div></div>');
          runStep(idx+1);
        }, 600);

      } else if(op.category === 'rpa-open-xlsx'){
        // Show file picker
        var host = document.createElement('div');
        host.className = 'rpa-step-host';
        host.innerHTML = ''+
          '<div class="rpa-drop-zone" id="rpaDropZone-'+idx+'">'+
            '<svg class="icon" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="15" y2="17"/></svg>'+
            '<div class="title">Drop Servicenow worker incidents.xlsx here</div>'+
            '<div class="sub">…or click to browse. The bot will parse rows in-browser using SheetJS, then create one ServiceNow incident per row via REST.</div>'+
            '<div class="actions">'+
              '<button class="rpa-btn primary" onclick="document.getElementById(\'rpaFileInput-'+idx+'\').click()">'+
                '<svg viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>'+
                'Choose File'+
              '</button>'+
              '<button class="rpa-btn secondary" onclick="rpaDownloadTemplate()">'+
                '<svg viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>'+
                'Download Template'+
              '</button>'+
            '</div>'+
            '<input type="file" id="rpaFileInput-'+idx+'" accept=".xlsx,.xls" style="display:none"/>'+
          '</div>';
        infoBox.appendChild(host);

        var dropZone = host.querySelector('.rpa-drop-zone');
        var fileInput = host.querySelector('input[type=file]');

        var handleFile = function(file){
          rpaState.file = file;
          dropZone.outerHTML = ''+
            '<div class="rpa-file-meta">'+
              '<div class="rpa-file-icon">XLSX</div>'+
              '<div class="rpa-file-info"><div class="rpa-file-name">'+fdEsc(file.name)+'</div><div class="rpa-file-stats">'+(file.size/1024).toFixed(1)+' KB · loaded into bot memory</div></div>'+
            '</div>';
          rpaSucceed(stepEl);
          setTimeout(function(){ runStep(idx+1); }, 400);
        };

        fileInput.addEventListener('change', function(e){
          var f = e.target.files && e.target.files[0];
          if(f) handleFile(f);
        });
        // Click anywhere in the dropzone (not on the buttons themselves) to open the picker
        dropZone.addEventListener('click', function(e){
          if(e.target.closest('button') || e.target.closest('input')) return;
          fileInput.click();
        });
        dropZone.addEventListener('dragover', function(e){ e.preventDefault(); dropZone.classList.add('dragging'); });
        dropZone.addEventListener('dragleave', function(){ dropZone.classList.remove('dragging'); });
        dropZone.addEventListener('drop', function(e){
          e.preventDefault(); dropZone.classList.remove('dragging');
          var f = e.dataTransfer.files && e.dataTransfer.files[0];
          if(f) handleFile(f);
        });

      } else if(op.category === 'rpa-read-rows'){
        // Real SheetJS parsing
        if(typeof XLSX === 'undefined'){
          rpaFail(stepEl, 'SheetJS library not loaded. Check your network connection — this requires the xlsx CDN.');
          setTimeout(function(){ runStep(idx+1); }, 500);
          return;
        }
        var reader = new FileReader();
        reader.onload = function(e){
          try {
            var data = new Uint8Array(e.target.result);
            var wb = XLSX.read(data, { type:'array' });
            var sheetName = wb.SheetNames[0];
            var ws = wb.Sheets[sheetName];
            var rows = XLSX.utils.sheet_to_json(ws, { defval:'', raw:false });
            rpaState.rows = rows;

            // Render preview table
            var prev = document.createElement('div');
            prev.className = 'rpa-step-host';
            var cols = rows.length ? Object.keys(rows[0]) : [];
            var headHtml = cols.map(function(c){return '<th>'+fdEsc(c)+'</th>';}).join('');
            var rowsHtml = rows.slice(0, 50).map(function(r){
              return '<tr>'+cols.map(function(c){return '<td>'+fdEsc(String(r[c]||''))+'</td>';}).join('')+'</tr>';
            }).join('');
            prev.innerHTML = ''+
              '<div style="font-size:9pt;color:var(--txt-2);margin-bottom:8px"><strong style="color:var(--txt-1)">'+rows.length+' rows</strong> read from sheet "<code style="font-family:var(--font-family-mono);background:var(--surface-2);padding:1px 5px;border-radius:3px">'+fdEsc(sheetName)+'</code>" · '+cols.length+' columns ('+cols.slice(0,5).join(', ')+(cols.length>5?', …':'')+')</div>'+
              '<div class="rpa-preview"><table><thead><tr>'+headHtml+'</tr></thead><tbody>'+rowsHtml+'</tbody></table></div>'+
              (rows.length>50 ? '<div style="font-size:9pt;color:var(--txt-muted);margin-top:5px">Showing first 50 rows in preview. All '+rows.length+' will be processed.</div>' : '');
            infoBox.appendChild(prev);
            rpaSucceed(stepEl);
            setTimeout(function(){ runStep(idx+1); }, 600);
          } catch(err){
            rpaFail(stepEl, 'Excel parsing error: '+err.message);
            setTimeout(function(){ runStep(idx+1); }, 500);
          }
        };
        reader.onerror = function(){
          rpaFail(stepEl, 'Could not read file — '+(reader.error && reader.error.message));
          setTimeout(function(){ runStep(idx+1); }, 500);
        };
        reader.readAsArrayBuffer(rpaState.file);

      } else if(op.category === 'rpa-validate'){
        setTimeout(function(){
          var valid = [];
          var invalid = [];
          rpaState.rows.forEach(function(r, i){
            var errs = [];
            if(!r.short_description && !r['Short Description']) errs.push('missing short_description');
            var u = r.urgency || r.Urgency;
            if(u && [1,2,3,'1','2','3'].indexOf(u) === -1) errs.push('invalid urgency');
            var imp = r.impact || r.Impact;
            if(imp && [1,2,3,'1','2','3'].indexOf(imp) === -1) errs.push('invalid impact');
            if(errs.length){ invalid.push({ row:i+1, errs:errs }); }
            else { valid.push(r); }
          });
          rpaState.validRows = valid;
          var meta = document.createElement('div');
          meta.className = 'rpa-step-host';
          meta.innerHTML = '<div style="font-size:10pt;color:var(--txt-2)"><strong style="color:var(--green)">'+valid.length+' valid</strong> · <strong style="color:'+(invalid.length?'var(--red)':'var(--txt-muted)')+'">'+invalid.length+' invalid</strong> '+(invalid.length ? '<span style="font-size:9pt;color:var(--red);margin-left:8px">('+invalid.slice(0,3).map(function(x){return 'row '+x.row+': '+x.errs.join(', ');}).join('; ')+(invalid.length>3?'…':'')+')</span>' : '')+'</div>';
          infoBox.appendChild(meta);
          rpaSucceed(stepEl);
          setTimeout(function(){ runStep(idx+1); }, 500);
        }, 400);

      } else if(op.isRPALoop){
        // Loop: one REST call per valid row
        var conn = fdConnections.find(function(c){return c.id===op.connectionId;});
        if(!conn || !rpaState.validRows.length){
          rpaFail(stepEl, !conn ? 'ServiceNow connection missing.' : 'No valid rows to process.');
          setTimeout(function(){ runStep(idx+1); }, 400);
          return;
        }

        // Replace step name with LIVE tag
        infoBox.querySelector('.fd-pub-step-name').innerHTML = 'Step '+(idx+1)+': '+fdEsc(op.name)+'<span class="fd-pub-live-tag">LIVE</span>';

        var host = document.createElement('div');
        host.className = 'rpa-step-host';
        host.innerHTML = '<div class="rpa-console" id="rpaConsole-'+idx+'"></div><div class="rpa-queue" id="rpaQueue-'+idx+'"></div>';
        infoBox.appendChild(host);

        var consoleEl = host.querySelector('.rpa-console');
        var queueEl   = host.querySelector('.rpa-queue');

        // Pre-render queue items
        rpaState.validRows.forEach(function(r, i){
          var q = document.createElement('div');
          q.className = 'rpa-queue-item';
          q.dataset.idx = i;
          q.innerHTML = '<span class="label">QUEUE</span><span class="num">#'+(i+1)+'</span>';
          queueEl.appendChild(q);
        });

        rpaConsoleLog(consoleEl, 'bot',  '['+rpaState.bot.name+'] Spawning worker pool for '+rpaState.validRows.length+' queue items.');
        rpaConsoleLog(consoleEl, 'info', '[connector] '+conn.name+' · base '+conn.baseUrl);

        var done = 0, ok = 0, fail = 0;

        function processOne(i){
          if(i >= rpaState.validRows.length){
            rpaConsoleLog(consoleEl, 'summary', '[bot] Run complete — '+ok+' created · '+fail+' failed.');
            // Finalize step
            stepEl.classList.remove('pending');
            stepEl.classList.add(fail ? (ok ? 'success' : 'error') : 'success');
            stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>';
            setTimeout(function(){ runStep(idx+1); }, 400);
            return;
          }
          var row = rpaState.validRows[i];
          var qItem = queueEl.querySelector('[data-idx="'+i+'"]');
          qItem.classList.add('processing');
          qItem.querySelector('.label').textContent = 'PROCESSING';

          rpaConsoleLog(consoleEl, 'proc', '[item #'+(i+1)+'] Processing → POST /api/now/table/incident · short="'+(row.short_description||row['Short Description']||'').slice(0,40)+(((row.short_description||row['Short Description']||'').length>40)?'…':'')+'"');

          // Substitute row fields into the body template
          var bodyTemplate = (op.config && op.config.body) || '{}';
          var bodyStr = bodyTemplate
            .replace(/\{\{short_description\}\}/g, fdEscJson(row.short_description||row['Short Description']||'(no description)'))
            .replace(/\{\{description\}\}/g,       fdEscJson(row.description||row.Description||row.short_description||row['Short Description']||''))
            .replace(/\{\{urgency\}\}/g,           String(row.urgency||row.Urgency||'2'))
            .replace(/\{\{impact\}\}/g,            String(row.impact||row.Impact||'2'))
            .replace(/\{\{category\}\}/g,          fdEscJson(row.category||row.Category||'inquiry'))
            .replace(/\{\{caller_id\}\}/g,         fdEscJson(row.caller_id||row.Caller||'admin'));

          var url = conn.baseUrl.replace(/\/+$/,'') + op.actionPath;
          var startedAt = Date.now();

          fetch(url, {
            method:'POST',
            headers:{
              'Authorization': 'Basic ' + btoa(conn.authUsername+':'+conn.authPassword),
              'Content-Type':'application/json',
              'Accept':'application/json'
            },
            body: bodyStr
          }).then(function(res){
            var ms = Date.now()-startedAt;
            if(res.ok){
              return res.json().then(function(d){
                var rec = d.result || {};
                qItem.classList.remove('processing'); qItem.classList.add('success');
                qItem.innerHTML = '<span class="label">'+(rec.number||'OK')+'</span><span class="num">'+ms+' ms</span>';
                rpaConsoleLog(consoleEl, 'ok', '[item #'+(i+1)+'] ✓ HTTP 201 · created <span class="inc">'+(rec.number||'INC?')+'</span> · '+ms+' ms');
                rpaState.results.push({ idx:i+1, ok:true, number:rec.number, sysId:rec.sys_id, row:row });
                ok++; done++;
                setTimeout(function(){ processOne(i+1); }, 220);
              });
            } else {
              return res.text().then(function(t){
                qItem.classList.remove('processing'); qItem.classList.add('fail');
                qItem.innerHTML = '<span class="label">HTTP '+res.status+'</span><span class="num">#'+(i+1)+'</span>';
                rpaConsoleLog(consoleEl, 'fail', '[item #'+(i+1)+'] ✗ HTTP '+res.status+' · '+t.slice(0,80));
                rpaState.results.push({ idx:i+1, ok:false, error:'HTTP '+res.status, row:row });
                fail++; done++;
                setTimeout(function(){ processOne(i+1); }, 220);
              });
            }
          }).catch(function(err){
            qItem.classList.remove('processing'); qItem.classList.add('fail');
            qItem.innerHTML = '<span class="label">CORS</span><span class="num">#'+(i+1)+'</span>';
            rpaConsoleLog(consoleEl, 'fail', '[item #'+(i+1)+'] ✗ Browser blocked: '+err.message+' (CORS — see step summary for fix)');
            rpaState.results.push({ idx:i+1, ok:false, error:'CORS: '+err.message, row:row });
            fail++; done++;
            setTimeout(function(){ processOne(i+1); }, 220);
          });
        }

        processOne(0);

      } else if(op.category === 'rpa-summary'){
        setTimeout(function(){
          var ok = rpaState.results.filter(function(r){return r.ok;}).length;
          var fail = rpaState.results.filter(function(r){return !r.ok;}).length;
          var total = rpaState.results.length;

          var summary = document.createElement('div');
          summary.className = 'rpa-summary' + (fail ? ' partial' : '');
          summary.innerHTML = ''+
            '<div class="rpa-summary-head">'+
              '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><polyline points="20 6 9 17 4 12"/></svg>'+
              (fail===0 ? 'RPA Run Complete · all incidents created' : (ok>0 ? 'RPA Run Partial · '+ok+' of '+total+' incidents created' : 'RPA Run Failed · no incidents created'))+
            '</div>'+
            '<div class="rpa-summary-stats">'+
              '<div class="rpa-summary-stat"><div class="rpa-summary-stat-val">'+rpaState.rows.length+'</div><div class="rpa-summary-stat-label">Rows Read</div></div>'+
              '<div class="rpa-summary-stat"><div class="rpa-summary-stat-val">'+rpaState.validRows.length+'</div><div class="rpa-summary-stat-label">Valid Rows</div></div>'+
              '<div class="rpa-summary-stat"><div class="rpa-summary-stat-val green">'+ok+'</div><div class="rpa-summary-stat-label">Created</div></div>'+
              '<div class="rpa-summary-stat"><div class="rpa-summary-stat-val '+(fail?'red':'green')+'">'+fail+'</div><div class="rpa-summary-stat-label">Failed</div></div>'+
            '</div>'+
            (rpaState.results.length ? ''+
              '<div style="font-size:9pt;color:var(--txt-muted);text-transform:uppercase;letter-spacing:0.4px;font-weight:600;margin-top:8px">Per-Row Result</div>'+
              '<div class="rpa-summary-list">'+
                rpaState.results.map(function(r){
                  if(r.ok){
                    return '<div class="rpa-summary-list-item ok"><span class="num">#'+r.idx+'</span><span class="icon"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg></span><span class="text">Created <strong>'+fdEsc(r.number||'')+'</strong> for "'+fdEsc((r.row.short_description||r.row['Short Description']||'').slice(0,60))+'"</span></div>';
                  } else {
                    return '<div class="rpa-summary-list-item fail"><span class="num">#'+r.idx+'</span><span class="icon"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></span><span class="text">'+fdEsc(r.error||'Failed')+' — "'+fdEsc((r.row.short_description||r.row['Short Description']||'').slice(0,60))+'"</span></div>';
                  }
                }).join('')+
              '</div>'+
              (fail && fail===total ? ''+
                '<div style="font-size:9pt;color:var(--txt-muted);margin-top:10px;line-height:1.5">'+
                  '<strong>All calls blocked by CORS?</strong> In ServiceNow, navigate to <code style="font-family:var(--font-family-mono);background:var(--surface-2);padding:1px 5px;border-radius:3px">System Web Services → REST → CORS Rules</code> and add a rule allowing the page origin (<code style="font-family:var(--font-family-mono);background:var(--surface-2);padding:1px 5px;border-radius:3px">file://</code> or your dev host) for POST on <code style="font-family:var(--font-family-mono);background:var(--surface-2);padding:1px 5px;border-radius:3px">/api/now/table/incident</code>.'+
                '</div>' : '')+
            '' : '');
          infoBox.appendChild(summary);
          rpaSucceed(stepEl);
          setTimeout(function(){ runStep(idx+1); }, 400);
        }, 400);

      } else {
        setTimeout(function(){ rpaSucceed(stepEl); runStep(idx+1); }, 400);
      }
    }

    function finishUp(){
      closeBtn.style.display = '';
      doneBtn.style.display = '';
      var ok = rpaState.results.filter(function(r){return r.ok;}).length;
      if(!isTestRun){
        fdEditorState.status = 'published';
        if(fdEditorState.flowId){
          var f = fdFlows.find(function(x){return x.id===fdEditorState.flowId;});
          if(f){
            f.status = 'published';
            f.lastRun = new Date().toISOString().replace('T',' ').slice(0,16);
          }
        }
        title.innerHTML = '✓ RPA Workflow Published · '+ok+' incidents created<span class="rpa-tag">RPA BOT</span>';
      } else {
        title.innerHTML = '✓ RPA Test Run Complete · '+ok+' incidents created<span class="rpa-tag">RPA BOT</span>';
      }
      sub.textContent = 'Bot processed '+rpaState.results.length+' queue items. Real ServiceNow records were created on '+(fdConnections.find(function(c){return c.type==='ServiceNow';})||{}).baseUrl+'.';
    }

    runStep(0);
  }

  // Helpers
  function rpaSucceed(stepEl, extraHtml){
    stepEl.classList.remove('pending'); stepEl.classList.add('success');
    stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>';
    if(extraHtml){
      var wrap = document.createElement('div'); wrap.innerHTML = extraHtml;
      stepEl.querySelector('.fd-pub-step-info').appendChild(wrap.firstChild);
    }
    var b = document.getElementById('fdPubBody'); if(b) b.scrollTop = b.scrollHeight;
  }
  function rpaFail(stepEl, msg){
    stepEl.classList.remove('pending'); stepEl.classList.add('error');
    stepEl.querySelector('.fd-pub-step-icon').innerHTML = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>';
    var meta = document.createElement('div');
    meta.className = 'fd-pub-step-meta';
    meta.style.color = 'var(--red)';
    meta.textContent = msg;
    stepEl.querySelector('.fd-pub-step-info').appendChild(meta);
  }
  function rpaConsoleLog(consoleEl, kind, msg){
    var line = document.createElement('div');
    line.className = 'rpa-console-line ' + kind;
    var t = new Date();
    var ts = String(t.getHours()).padStart(2,'0')+':'+String(t.getMinutes()).padStart(2,'0')+':'+String(t.getSeconds()).padStart(2,'0');
    line.innerHTML = '<span class="ts">'+ts+'</span> '+msg;
    consoleEl.appendChild(line);
    consoleEl.scrollTop = consoleEl.scrollHeight;
  }
  function fdEscJson(s){
    return String(s).replace(/\\/g,'\\\\').replace(/"/g,'\\"').replace(/\n/g,'\\n').replace(/\r/g,'\\r').replace(/\t/g,'\\t');
  }

