  // ── Logo helpers (type → CSS class + inline SVG) ──
  function fdConnLogoClass(type){
    var map = {
      'REST API':'l-rest', 'ServiceNow':'l-snow', 'Jira':'l-jira',
      'Slack':'l-slack', 'Webhook':'l-webhook', 'GraphQL':'l-rest',
      'SOAP':'l-rest', 'Custom':'l-custom',
      'Autodesk ACC':'l-autodesk',
      'ServiceNow UI':'l-snowui',
      'Database':'l-db', 'Excel':'l-excel'
    };
    return map[type] || 'l-rest';
  }
  function fdConnLogoSvg(type){
    if(type==='ServiceNow') return '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M8 12a4 4 0 1 1 8 0 4 4 0 0 1-8 0z"/></svg>';
    if(type==='Jira')       return '<svg viewBox="0 0 24 24"><path d="M11 2L2 11l9 9 9-9-9-9z"/><path d="M11 8l-3 3 3 3"/></svg>';
    if(type==='Slack')      return '<svg viewBox="0 0 24 24"><rect x="3" y="9" width="6" height="2" rx="1"/><rect x="9" y="3" width="2" height="6" rx="1"/><rect x="15" y="13" width="6" height="2" rx="1"/><rect x="13" y="15" width="2" height="6" rx="1"/></svg>';
    if(type==='Webhook')    return '<svg viewBox="0 0 24 24"><circle cx="12" cy="6" r="3"/><path d="M9 8l-4 8"/><path d="M15 8l4 8"/><circle cx="5" cy="18" r="3"/><circle cx="19" cy="18" r="3"/></svg>';
    if(type==='Autodesk ACC') return '<svg viewBox="0 0 24 24"><path d="M12 3 L3 21 L21 21 Z"/><line x1="8" y1="15" x2="16" y2="15"/></svg>';
    if(type==='ServiceNow UI') return '<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="14" rx="2"/><line x1="3" y1="8" x2="21" y2="8"/><circle cx="6" cy="5.5" r="0.6" fill="#fff"/><polygon points="13 14 13 21 15 19 16.5 21 18 20 16.5 18 18.5 17.5"/></svg>';
    if(type==='Database')   return '<svg viewBox="0 0 24 24"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v6c0 1.66 3.58 3 8 3s8-1.34 8-3V5"/><path d="M4 11v6c0 1.66 3.58 3 8 3s8-1.34 8-3v-6"/></svg>';
    if(type==='Excel')      return '<svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="15" y2="17"/><line x1="9" y1="13" x2="15" y2="17"/><line x1="15" y1="13" x2="9" y2="17"/></svg>';
    // REST API / generic
    return '<svg viewBox="0 0 24 24"><path d="M10 14a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 10a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>';
  }
  function fdConnStatusLabel(s){
    return s==='connected' ? 'Connected' : s==='error' ? 'Error' : 'Disconnected';
  }

  // ── Format helpers (corporate format standards) ──
  var _fdMonths = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  function fdFmtDate(str){
    if(!str || str==='never') return 'never';
    var d = new Date(str.replace(' ','T'));
    if(isNaN(d.getTime())) return str;
    var dd = ('0'+d.getDate()).slice(-2);
    var mmm = _fdMonths[d.getMonth()];
    var yy = String(d.getFullYear()).slice(-2);
    return dd+'-'+mmm+'-'+yy;
  }
  function fdFmtDateTime(str){
    if(!str || str==='never') return 'never';
    var d = new Date(str.replace(' ','T'));
    if(isNaN(d.getTime())) return str;
    var dd = ('0'+d.getDate()).slice(-2);
    var mmm = _fdMonths[d.getMonth()];
    var yy = String(d.getFullYear()).slice(-2);
    var hh = ('0'+d.getHours()).slice(-2);
    var mi = ('0'+d.getMinutes()).slice(-2);
    return dd+'-'+mmm+'-'+yy+' '+hh+':'+mi;
  }
  function fdFmtInt(n){
    if(n==null) return '0';
    return Number(n).toLocaleString('en-US');
  }

  // ── List page ──
  function renderConnections(){ fdRenderConnections(); }
  function fdRenderConnections(){
    var grid = document.getElementById('fdConnGrid');
    if(!grid) return;
    var q  = ((document.getElementById('fdConnSearch')||{}).value || '').toLowerCase().trim();
    var tf = (document.getElementById('fdConnTypeFilter')||{}).value || '';
    var sf = (document.getElementById('fdConnStatusFilter')||{}).value || '';

    var rows = fdConnections.filter(function(c){
      if(tf && c.type!==tf) return false;
      if(sf && c.status!==sf) return false;
      if(q){
        var hay = (c.name+' '+c.type+' '+(c.baseUrl||'')+' '+(c.description||'')).toLowerCase();
        if(hay.indexOf(q)===-1) return false;
      }
      return true;
    });

    var cnt = document.getElementById('fdConnCount');
    if(cnt) cnt.textContent = fdFmtInt(rows.length)+' connection'+(rows.length===1?'':'s');

    if(rows.length===0){
      grid.innerHTML = '<div class="fd-no-conn-msg" style="grid-column:1/-1"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>No connections match your filters. <a onclick="fdOpenConnEditor(null)">Create one</a> or clear the filters.</div>';
      return;
    }

    grid.innerHTML = rows.map(function(c){
      return ''+
        '<div class="fd-conn-card" onclick="fdOpenConnEditor('+c.id+')">'+
          '<div class="fd-conn-status-dot '+c.status+'">'+fdConnStatusLabel(c.status)+'</div>'+
          '<div class="fd-conn-card-head">'+
            '<div class="fd-conn-logo '+fdConnLogoClass(c.type)+'">'+fdConnLogoSvg(c.type)+'</div>'+
            '<div style="flex:1;min-width:0;padding-right:80px">'+
              '<div class="fd-conn-name">'+fdEsc(c.name)+'</div>'+
              '<span class="fd-conn-type-tag">'+fdEsc(c.type)+'</span>'+
            '</div>'+
          '</div>'+
          '<div class="fd-conn-desc">'+fdEsc(c.description||'')+'</div>'+
          '<div class="fd-conn-meta">'+
            '<span class="fd-conn-actions-count"><strong>'+fdFmtInt(c.actions?c.actions.length:0)+'</strong> action'+(c.actions&&c.actions.length===1?'':'s')+' · last tested '+fdEsc(fdFmtDateTime(c.lastTested)||'never')+'</span>'+
            '<div class="fd-conn-meta-actions" onclick="event.stopPropagation()">'+
              '<button title="Test now" onclick="fdQuickTestConn('+c.id+',this)"><svg viewBox="0 0 24 24"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg></button>'+
              '<button title="Edit" onclick="fdOpenConnEditor('+c.id+')"><svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>'+
              '<button title="Delete" onclick="fdDeleteConn('+c.id+')"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg></button>'+
            '</div>'+
          '</div>'+
        '</div>';
    }).join('');
  }

  function fdQuickTestConn(id, btn){
    var c = fdConnections.find(function(x){return x.id===id;}); if(!c) return;
    var orig = btn.innerHTML;
    btn.innerHTML = '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg>';
    btn.disabled = true;
    setTimeout(function(){
      // Random outcome but biased to success
      var ok = Math.random() > 0.15;
      c.status = ok ? 'connected' : 'error';
      c.lastTested = new Date().toISOString().replace('T',' ').slice(0,16);
      btn.innerHTML = orig; btn.disabled = false;
      fdRenderConnections();
    }, 1100);
  }
  function fdDeleteConn(id){
    var c = fdConnections.find(function(x){return x.id===id;}); if(!c) return;
    // Check if any flow operations depend on it
    var inUse = false;
    fdFlows.forEach(function(){}); // (flow ops aren't persisted in mock fdFlows yet, only in editor state)
    if(fdEditorState && fdEditorState.operations){
      inUse = fdEditorState.operations.some(function(o){return o.connectionId===id;});
    }
    var msg = 'Delete connection "'+c.name+'"?';
    if(inUse) msg += '\n\nWarning: this connection is referenced by operations in the flow you currently have open.';
    if(!confirm(msg)) return;
    fdConnections = fdConnections.filter(function(x){return x.id!==id;});
    fdRenderConnections();
  }

  // ── Connection editor modal ──
  function fdOpenConnEditor(id){
    if(id){
      var src = fdConnections.find(function(c){return c.id===id;}); if(!src) return;
      fdConnEditState = JSON.parse(JSON.stringify(src));
      document.getElementById('fdConnEditorTitle').textContent = 'Edit Connection — '+src.name;
    } else {
      fdConnEditState = {
        id: null, name:'', type:'REST API', description:'',
        baseUrl:'', authMethod:'Bearer Token', headers:{},
        actions:[], status:'disconnected'
      };
      document.getElementById('fdConnEditorTitle').textContent = 'New Connection';
    }
    // Populate fields
    document.getElementById('fdConnName').value = fdConnEditState.name || '';
    document.getElementById('fdConnType').value = fdConnEditState.type || 'REST API';
    document.getElementById('fdConnDesc').value = fdConnEditState.description || '';
    document.getElementById('fdConnUrl').value  = fdConnEditState.baseUrl || '';
    document.getElementById('fdConnAuth').value = fdConnEditState.authMethod || 'None';
    document.getElementById('fdConnTestResult').innerHTML = '';
    fdRenderAuthFields();
    fdRenderHeaderRows();
    document.getElementById('fdConnEditorModal').classList.add('open');
  }
  function fdCloseConnEditor(){
    document.getElementById('fdConnEditorModal').classList.remove('open');
    fdConnEditState = null;
  }
  function fdMaybeCloseConnEditor(e){
    if(e.target.id==='fdConnEditorModal') fdCloseConnEditor();
  }

  function fdRenderAuthFields(){
    var box = document.getElementById('fdAuthFields');
    if(!box) return;
    var method = document.getElementById('fdConnAuth').value;
    var st = fdConnEditState || {};
    var html = '';
    if(method==='API Key'){
      html = ''+
        '<div class="fd-form-row">'+
          '<div class="fd-form-group"><div class="fd-form-label">Header Name</div><input type="text" class="fd-form-input" id="fdAuthHeader" value="'+fdEsc(st.authHeader||'X-API-Key')+'"/></div>'+
          '<div class="fd-form-group"><div class="fd-form-label">API Key</div><input type="password" class="fd-form-input" id="fdAuthKey" value="'+fdEsc(st.authKey||'')+'" placeholder="Paste your API key"/></div>'+
        '</div>';
    } else if(method==='Bearer Token'){
      html = ''+
        '<div class="fd-form-group"><div class="fd-form-label">Bearer Token</div><input type="password" class="fd-form-input" id="fdAuthToken" value="'+fdEsc(st.authToken||'')+'" placeholder="Paste the token (sent as: Authorization: Bearer ...)"/></div>';
    } else if(method==='Basic Auth'){
      html = ''+
        '<div class="fd-form-row">'+
          '<div class="fd-form-group"><div class="fd-form-label">Username</div><input type="text" class="fd-form-input" id="fdAuthUser" value="'+fdEsc(st.authUser||'')+'"/></div>'+
          '<div class="fd-form-group"><div class="fd-form-label">Password</div><input type="password" class="fd-form-input" id="fdAuthPass" value="'+fdEsc(st.authPass||'')+'"/></div>'+
        '</div>';
    } else if(method==='OAuth 2.0'){
      html = ''+
        '<div class="fd-form-row">'+
          '<div class="fd-form-group"><div class="fd-form-label">Client ID</div><input type="text" class="fd-form-input" id="fdAuthClientId" value="'+fdEsc(st.authClientId||'')+'"/></div>'+
          '<div class="fd-form-group"><div class="fd-form-label">Client Secret</div><input type="password" class="fd-form-input" id="fdAuthClientSecret" value="'+fdEsc(st.authClientSecret||'')+'"/></div>'+
        '</div>'+
        '<div class="fd-form-group"><div class="fd-form-label">Token URL</div><input type="text" class="fd-form-input" id="fdAuthTokenUrl" value="'+fdEsc(st.authTokenUrl||'')+'" placeholder="https://login.example.com/oauth/token"/></div>'+
        '<div class="fd-form-group"><div class="fd-form-label">Scope</div><input type="text" class="fd-form-input" id="fdAuthScope" value="'+fdEsc(st.authScope||'')+'" placeholder="read write"/></div>';
    } else {
      // None
      html = '<div class="fd-form-help" style="padding:8px 0">No authentication will be applied. Suitable for public APIs and webhook URLs that include their own secret.</div>';
    }
    box.innerHTML = html;
  }

  function fdRenderHeaderRows(){
    var st = fdConnEditState || {headers:{}};
    var tbody = document.querySelector('#fdConnHeaders tbody');
    if(!tbody) return;
    var keys = Object.keys(st.headers||{});
    if(keys.length===0) keys = [''];
    tbody.innerHTML = keys.map(function(k, i){
      return ''+
        '<tr data-row="'+i+'">'+
          '<td><input type="text" placeholder="Header name (e.g. Content-Type)" value="'+fdEsc(k)+'" data-field="key"/></td>'+
          '<td><input type="text" placeholder="Value" value="'+fdEsc((st.headers||{})[k]||'')+'" data-field="val"/></td>'+
          '<td><button class="fd-kv-del" type="button" onclick="fdRemoveHeaderRow('+i+')"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg></button></td>'+
        '</tr>';
    }).join('');
  }
  function fdAddHeaderRow(){
    var st = fdConnEditState; if(!st) return;
    fdSyncHeadersFromForm();
    if(!st.headers) st.headers = {};
    // Add a placeholder empty key
    var i = 0;
    while(st.headers['__new'+i] !== undefined) i++;
    st.headers['__new'+i] = '';
    fdRenderHeaderRows();
  }
  function fdRemoveHeaderRow(idx){
    var st = fdConnEditState; if(!st) return;
    fdSyncHeadersFromForm();
    var keys = Object.keys(st.headers||{});
    if(idx>=0 && idx<keys.length){ delete st.headers[keys[idx]]; }
    fdRenderHeaderRows();
  }
  function fdSyncHeadersFromForm(){
    var st = fdConnEditState; if(!st) return;
    var rows = document.querySelectorAll('#fdConnHeaders tbody tr');
    var newHeaders = {};
    rows.forEach(function(tr){
      var k = (tr.querySelector('[data-field=key]')||{}).value || '';
      var v = (tr.querySelector('[data-field=val]')||{}).value || '';
      k = k.trim();
      if(k) newHeaders[k] = v;
    });
    st.headers = newHeaders;
  }

  function fdReadConnFromForm(){
    var st = fdConnEditState; if(!st) return null;
    st.name        = document.getElementById('fdConnName').value.trim();
    st.type        = document.getElementById('fdConnType').value;
    st.description = document.getElementById('fdConnDesc').value;
    st.baseUrl     = document.getElementById('fdConnUrl').value.trim();
    st.authMethod  = document.getElementById('fdConnAuth').value;
    // Auth fields
    var byId = function(id){ return (document.getElementById(id)||{}).value; };
    if(st.authMethod==='API Key')      { st.authHeader = byId('fdAuthHeader'); st.authKey = byId('fdAuthKey'); }
    if(st.authMethod==='Bearer Token') { st.authToken  = byId('fdAuthToken'); }
    if(st.authMethod==='Basic Auth')   { st.authUser = byId('fdAuthUser'); st.authPass = byId('fdAuthPass'); }
    if(st.authMethod==='OAuth 2.0')    {
      st.authClientId = byId('fdAuthClientId'); st.authClientSecret = byId('fdAuthClientSecret');
      st.authTokenUrl = byId('fdAuthTokenUrl'); st.authScope = byId('fdAuthScope');
    }
    fdSyncHeadersFromForm();
    return st;
  }

  function fdTestConnection(){
    var st = fdReadConnFromForm(); if(!st) return;
    var box = document.getElementById('fdConnTestResult');
    if(!st.baseUrl){ box.innerHTML = '<div class="fd-test-result fail"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>Base URL is required.</div>'; return; }

    // ── Real ServiceNow test (Basic Auth GET to /api/now/table/sys_user) ──
    if(st.type === 'ServiceNow' && st.authUsername && st.authPassword){
      box.innerHTML = '<div class="fd-test-result pending"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Calling '+fdEsc(st.baseUrl)+'/api/now/table/sys_user (real request)…</div>';
      var url = st.baseUrl.replace(/\/+$/,'') + '/api/now/table/sys_user?sysparm_limit=1&sysparm_fields=user_name,sys_id';
      var startedAt = Date.now();
      fetch(url, {
        method:'GET',
        headers:{
          'Authorization': 'Basic ' + btoa(st.authUsername+':'+st.authPassword),
          'Accept':'application/json'
        }
      }).then(function(res){
        var ms = Date.now()-startedAt;
        if(res.ok){
          return res.json().then(function(d){
            var who = (d.result && d.result[0] && d.result[0].user_name) || '(unknown)';
            box.innerHTML = '<div class="fd-test-result success"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>Connection successful — HTTP '+res.status+' in '+ms+' ms · authenticated as <code style="font-family:var(--font-family-mono);background:rgba(22,163,74,0.1);padding:1px 5px;border-radius:3px">'+fdEsc(who)+'</code></div>';
            st.status = 'connected'; st.lastTested = new Date().toISOString().replace('T',' ').slice(0,16);
          });
        } else {
          return res.text().then(function(t){
            box.innerHTML = '<div class="fd-test-result fail"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>Authentication failed — HTTP '+res.status+' '+fdEsc(res.statusText)+'<br><span style="font-size:9pt;color:var(--txt-muted)">Response: '+fdEsc(t.slice(0,200))+'</span></div>';
            st.status = 'error';
          });
        }
      }).catch(function(err){
        box.innerHTML = ''+
          '<div class="fd-test-result fail">'+
            '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>'+
            '<div>'+
              '<strong>Browser blocked the request</strong> ('+fdEsc(err.message||'CORS / network error')+')'+
              '<div style="font-size:9pt;color:var(--txt-muted);margin-top:6px;line-height:1.5">'+
              'ServiceNow has not allowed this origin to call its API. To make real calls work:<br>'+
              '<strong>1.</strong> In ServiceNow, navigate to <code style="font-family:var(--font-family-mono)">System Web Services → REST → CORS Rules</code><br>'+
              '<strong>2.</strong> Create a rule for the origin you\'re running this page from (e.g. <code style="font-family:var(--font-family-mono)">file://</code> or <code style="font-family:var(--font-family-mono)">http://localhost</code>) and allow the <code style="font-family:var(--font-family-mono)">/api/now/table/incident</code> endpoint with <code style="font-family:var(--font-family-mono)">GET, POST</code> methods.<br>'+
              '<strong>3.</strong> Verify with this curl from your terminal:<br>'+
              '<pre style="background:var(--surface-2);padding:8px;border-radius:5px;font-size:9pt;margin:5px 0;overflow:auto;white-space:pre-wrap;word-break:break-all">curl -u \''+fdEsc(st.authUsername)+':'+fdEsc(st.authPassword)+'\' \\\n  \''+fdEsc(url)+'\'</pre>'+
              '</div>'+
            '</div>'+
          '</div>';
        st.status = 'error';
      });
      return;
    }

    // ── Mock test for non-ServiceNow connections ──
    box.innerHTML = '<div class="fd-test-result pending"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Testing connection to '+fdEsc(st.baseUrl)+'…</div>';
    setTimeout(function(){
      var ok = Math.random() > 0.2;
      if(ok){
        box.innerHTML = '<div class="fd-test-result success"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>Connection successful — responded in '+(Math.floor(Math.random()*250)+50)+' ms with HTTP 200.</div>';
        st.status = 'connected';
      } else {
        box.innerHTML = '<div class="fd-test-result fail"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>Connection failed — HTTP 401 Unauthorized. Check your credentials and try again.</div>';
        st.status = 'error';
      }
      st.lastTested = new Date().toISOString().replace('T',' ').slice(0,16);
    }, 1300);
  }

  function fdSaveConnection(){
    var st = fdReadConnFromForm(); if(!st) return;
    if(!st.name){ alert('Please enter a connection name.'); return; }
    if(!st.baseUrl){ alert('Please enter a base URL.'); return; }

    if(st.id){
      // Update existing
      var idx = fdConnections.findIndex(function(c){return c.id===st.id;});
      if(idx>=0){
        // Preserve existing actions list (auto-defined templates)
        st.actions = fdConnections[idx].actions || [];
        fdConnections[idx] = st;
      }
    } else {
      // Create new
      st.id = (fdConnections.length ? Math.max.apply(null, fdConnections.map(function(c){return c.id;})) : 0) + 1;
      st.lastTested = st.lastTested || 'never';
      // Seed default actions based on type so the user has something to invoke
      st.actions = fdDefaultActionsForType(st.type);
      fdConnections.unshift(st);
    }
    fdCloseConnEditor();
    fdRenderConnections();
  }

  function fdDefaultActionsForType(type){
    if(type==='ServiceNow') return [
      { id:'snow-incident-'+Date.now(), label:'Create Incident', method:'POST', path:'/table/incident' },
      { id:'snow-update-'+Date.now(),   label:'Update Ticket',   method:'PATCH', path:'/table/incident/{sys_id}' }
    ];
    if(type==='Jira') return [
      { id:'jira-create-'+Date.now(),  label:'Create Issue',  method:'POST', path:'/issue' },
      { id:'jira-comment-'+Date.now(), label:'Add Comment',   method:'POST', path:'/issue/{key}/comment' }
    ];
    if(type==='Slack') return [
      { id:'slack-msg-'+Date.now(), label:'Send Channel Message', method:'POST', path:'/chat.postMessage' }
    ];
    if(type==='Webhook') return [
      { id:'wh-post-'+Date.now(), label:'POST Payload', method:'POST', path:'/' }
    ];
    if(type==='Autodesk ACC') return [
      { id:'acc-issue-'+Date.now(),    label:'Create Issue',         method:'POST', path:'/construction/issues/v1/projects/{projectId}/issues' },
      { id:'acc-rfi-'+Date.now(),      label:'Create RFI',           method:'POST', path:'/construction/rfis/v2/projects/{projectId}/rfis' },
      { id:'acc-dailylog-'+Date.now(), label:'Add Daily Log Entry',  method:'POST', path:'/construction/dailylogs/v2/projects/{projectId}/daily-logs' },
      { id:'acc-upload-'+Date.now(),   label:'Upload Document',      method:'POST', path:'/data/v1/projects/{projectId}/storage' }
    ];
    if(type==='ServiceNow UI') return [
      { id:'snowui-incident-'+Date.now(), label:'Login & Create Incident (UI)', method:'UI', path:'/incident.do?sys_id=-1', isReal:true, isUI:true },
      { id:'snowui-form-'+Date.now(),     label:'Login & Submit Catalog Form',  method:'UI', path:'/sc_cat_item.do?sys_id={item}', isReal:true, isUI:true }
    ];
    // Generic REST/GraphQL/SOAP/Custom
    return [
      { id:'rest-get-'+Date.now(),   label:'GET Resource',   method:'GET',   path:'/' },
      { id:'rest-post-'+Date.now(),  label:'Create Resource',method:'POST',  path:'/' },
      { id:'rest-patch-'+Date.now(), label:'Update Resource',method:'PATCH', path:'/{id}' }
    ];
  }


  /* ═══════════════════ OPERATION PICKER MODAL ═══════════════════ */
