  var arRunsGridInstance = null;
  function renderAgentRuns(){
    var gridEl = document.getElementById('arRunsGrid'); if(!gridEl) return;
    var dk = !document.documentElement.classList.contains('navbar-light');
    gridEl.className = dk ? 'ag-theme-alpine-dark' : 'ag-theme-alpine';

    var rowData = aiAgentRuns.map(function(r){
      return {
        id: r.id,
        agentName: r.agentName,
        inputSummary: JSON.stringify(r.input),
        verdict: r.verdict,
        duration: (r.durationMs/1000).toFixed(2)+'s',
        startedAt: fdFmtDateTime(r.startedAt),
        status: r.status
      };
    });

    var columnDefs = [
      { headerName:'Run', field:'id', width:100, sortable:true, filter:true,
        cellStyle: { fontFamily:'var(--font-family-mono)', color: dk ? 'rgba(200,215,240,0.7)' : 'var(--accent)' } },
      { headerName:'Agent', field:'agentName', width:220, sortable:true, filter:true,
        cellRenderer: function(p){ return '<span style="font-weight:500;color:var(--accent)">'+p.value+'</span>'; } },
      { headerName:'Input Summary', field:'inputSummary', flex:1, minWidth:200, sortable:true, filter:true,
        cellStyle: { fontFamily:'var(--font-family-mono)', fontSize:'9pt', color: dk ? '#c7cfe0' : '#475569' } },
      { headerName:'Verdict', field:'verdict', width:200, sortable:true, filter:true,
        cellRenderer: function(p){ var c = p.data.status==='error' ? '#FF0000' : (dk?'rgba(255,255,255,0.92)':'var(--txt-1)'); return '<span style="font-weight:600;color:'+c+'">'+p.value+'</span>'; } },
      { headerName:'Duration', field:'duration', width:120, sortable:true, filter:true,
        cellStyle: { fontFamily:'var(--font-family-mono)', fontSize:'9pt', textAlign:'center', color: dk ? '#c7cfe0' : '#475569' } },
      { headerName:'Started', field:'startedAt', width:180, sortable:true, filter:true,
        cellStyle: { fontFamily:'var(--font-family-mono)', fontSize:'9pt', color: dk ? '#c7cfe0' : '#475569' } },
      { headerName:'Trace', field:'status', width:120, sortable:true, filter:true,
        cellRenderer: function(p){ if(p.value==='success') return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:9pt;font-weight:600;color:#00B050;background:rgba(0,176,80,0.1);border:1px solid rgba(0,176,80,0.3);border-radius:12px;padding:2px 10px"><span style="width:7px;height:7px;border-radius:50%;background:#00B050;display:inline-block"></span>Success</span>'; return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:9pt;font-weight:600;color:#FF0000;background:rgba(255,0,0,0.1);border:1px solid rgba(255,0,0,0.3);border-radius:12px;padding:2px 10px"><span style="width:7px;height:7px;border-radius:50%;background:#FF0000;display:inline-block"></span>Error</span>'; },
        cellStyle: { textAlign:'right' } }
    ];

    if(arRunsGridInstance){ try{ arRunsGridInstance.destroy(); }catch(ex){} arRunsGridInstance=null; }

    var gridOptions = {
      columnDefs: columnDefs,
      rowData: rowData,
      animateRows: true,
      rowSelection: 'multiple',
      defaultColDef: { resizable:true, sortable:true, filter:true },
      domLayout: 'autoHeight',
      pagination: true,
      paginationPageSize: 20,
      paginationPageSizeSelector: [10, 20, 50, 100],
      suppressHorizontalScroll: false
    };

    gridEl.style.height = '';
    arRunsGridInstance = agGrid.createGrid(gridEl, gridOptions);
  }


