          if (currentRange === '30p')  return { lo: 60, hi: 89,  label: 'Past 30 Days' };
          if (currentRange === '90p')  return { lo: 0,  hi: 89,  label: 'Past 90 Days' };
          if (currentRange === '30f')  return { lo: 90, hi: 119, label: 'Next 30 Days' };
          return { lo: 0, hi: 119, label: 'Full 120 Days' };
